'use strict';
/* 4.28: рисунки духов и богов кельтской мифологии — каждый своей функцией (кисть — js/art-kit.js) */

Object.assign(SPIRIT_ART, {
  // Блуждающий огонёк: тёплый огонёк-капелька парит над мокрым газоном. Хохолок пламени загнут, как пальчик, сам огонёк
  // подмигивает и манит ручкой «сюда!»; вокруг вьётся петля из огоньков-точек (водит кругами), в лужице — отражение
  ce_wisp(K) {
    let s = K.aura('#ffb347', 92, 108, 0.45) + K.aura('#5eead4', 58, 104, 0.18);
    // петляющая тропка из огоньков
    s += ceDots('M30 164C14 132 26 96 56 96C82 96 82 130 60 132C42 134 42 110 62 110M140 56C164 40 188 60 178 86C170 106 146 100 152 84', '#ffe08a', 3.4, 9, 0.7);
    // мокрый газон и лужица с отражением
    s += `<ellipse cx="100" cy="175" rx="62" ry="7" fill="${K.rad([[0, '#7dd3fc', 0.45], [1, '#38bdf8', 0]])}"/><ellipse class="art-blink" cx="100" cy="175" rx="20" ry="3" fill="#ffd166" opacity=".55"/>`;
    const grass = 'M54 179q-2-12-9-18M59 179q0-15 4-23M64 179q3-10 9-14M136 179q-3-11-10-16M141 179q1-15 6-21M146 179q3-8 11-12';
    s += K.line(grass, '#2f4f12', 4) + K.line(grass, '#84cc16', 1.8);
    const body = 'M100 62C112 74 138 90 138 118C138 142 122 156 100 156C78 156 62 142 62 118C62 96 80 84 90 74C94 68 97 64 100 62Z';
    const arm = { c1: '#ffeab0', c2: '#ff9a3d', rim: '#b5fff0', rimK: 0.5, tex: false, lw: 2.2, line: '#a8400c' };
    // шлейф-хвостик
    let b = `<path d="M84 146C74 158 58 166 40 160C50 170 72 172 92 154Z" fill="${K.lin(['#ffd166', '#ff8a1f'])}" opacity=".8"/>`;
    // хохолок пламени
    b += K.g(K.flame(98, 80, 52, 36, '#fff3b0', '#ff8a1f'), 'rotate(10 98 80)');
    // ручки: левая упёрта в бочок, правая манит пальчиком
    b += K.vol('M66 120C56 122 48 130 48 140C52 146 60 144 64 138Z', arm);
    b += K.vol('M132 112C142 106 150 98 153 88C156 82 164 82 164 88C162 100 152 112 138 122Z', arm);
    b += K.line('M160 84C164 78 162 72 156 72', '#a8400c', 5.4) + K.line('M160 84C164 78 162 72 156 72', '#ffeab0', 2.8);
    // тельце-огонёк
    b += K.vol(body, { c1: '#fff1b8', c2: '#ff8a1f', rim: '#b5fff0', rimK: 0.55, hiK: 0.25, texK: 0.3, line: '#a8400c', lw: 2.6 });
    b += `<ellipse cx="100" cy="126" rx="30" ry="22" fill="${K.rad([[0, '#fffbe6', 0.85], [1, '#ffd166', 0]])}"/>`;
    b += K.gloss(80, 98, 9, 5, -40, 0.45);
    // мордочка: подмигивает и ухмыляется
    b += `<g class="art-eyes">${K.eye(86, 112, 11, { iris: '#ff7a1a', look: [0.4, 0.1] })}</g>` + K.line('M103 113Q112 104 121 113', K.INK, 3.2);
    b += K.blush(76, 128, 6) + K.blush(126, 128, 6) + K.mouth('grin', 101, 127, 18);
    s += K.g(b, '', 'art-float');
    s += K.spark(26, 70, 3.6, '#fff3b0', 'art-float') + K.spark(176, 128, 3, '#ffe08a') + K.spark(42, 34, 2.6, '#b5fff0') + K.spark(160, 30, 2.6, '#fff3b0', 'art-float');
    return s;
  },

  // Джек-фонарь: в Ирландии фонари резали из репы, а не из тыквы. Голова — резная репа с лиловой макушкой, ботвой и
  // проволочной дужкой, в прорезях глаз и рта горит свет; драный плащ с заплатами и шарф, в левой руке кривая клюка,
  // в правой — тот самый уголёк-огонёк (подрос из Блуждающего огонька и теперь светит Джеку)
  ce_jack(K) {
    const skin = { c1: '#efe2bd', c2: '#a8946a', rim: '#ffd9a0', tex: false, lw: 2, line: '#4a3a1c' };
    const cl = { c1: '#6b5a34', c2: '#261c0c', rim: '#ffcf80', rimK: 0.55, tex: false, lw: 2.6, line: '#140e06' };
    let s = K.aura('#ff8a1f', 96, 104, 0.45);
    // кривая клюка
    const stick = 'M40 96C34 90 38 82 46 84C50 86 50 92 46 96L54 178';
    s += K.line(stick, '#2a1a0c', 7) + K.line(stick, '#8a5a2c', 3.2);
    // драный плащ с заплатами
    const cloak = 'M100 100C122 100 136 112 142 130C148 146 150 160 152 172L144 167L138 176L130 168L122 176L114 168L106 176L98 168L90 176L82 168L74 176L66 168L58 173C52 160 54 146 60 130C66 112 78 100 100 100Z';
    s += K.vol(cloak, cl);
    s += K.line('M86 112C82 130 78 150 76 166M114 112C118 130 122 150 124 166M100 116V168', '#140e06', 1.8, { op: 0.4 });
    s += K.part('M66 138H80V152H66Z', '#8a3a2a', { line: '#2a1208', lw: 1.6 }) + K.stitch('M67.5 139.5H78.5V150.5H67.5Z', '#fde68a', 1.1);
    s += K.part('M118 148L132 146L134 159L120 161Z', '#3f6a4a', { line: '#10261a', lw: 1.6 }) + K.stitch('M119.5 149.5L130.5 147.8L132.2 157.8L121.2 159.6Z', '#fde68a', 1.1);
    // сапоги
    s += K.vol('M74 173C74 167 82 165 90 167C96 169 98 175 96 180H74Z', { ...cl, lw: 2 }) + K.vol('M126 173C126 167 118 165 110 167C104 169 102 175 104 180H126Z', { ...cl, lw: 2 });
    // левая рука на клюке
    s += K.vol('M74 112C62 116 52 124 46 132C48 140 56 142 60 138C64 130 72 124 82 120Z', cl);
    s += K.vol(K.ell(48, 132, 7.5, 7), skin);
    // правая рука с угольком
    s += K.vol('M126 112C138 114 148 120 154 130C150 138 142 138 138 134C134 128 128 124 120 122Z', cl);
    s += `<circle class="art-aura" cx="150" cy="118" r="20" fill="${K.rad([[0, '#fff3b0', 0.9], [0.4, '#ffb020', 0.5], [1, '#ff7a1a', 0]])}"/>`;
    s += K.flame(150, 131, 28, 19, '#fff3b0', '#ff7a1a');
    s += `<circle cx="147" cy="123" r="1.4" fill="${K.INK}"/><circle cx="153" cy="123" r="1.4" fill="${K.INK}"/>` + K.line('M147.5 126.5Q150 128.5 152.5 126.5', K.INK, 1.2);
    s += K.vol('M139 131C143 127 157 127 161 131C161 138 155 141 150 141C145 141 139 138 139 131Z', skin);
    // шарф
    s += K.part('M72 106C88 114 112 114 128 106L130 116C112 124 88 124 70 116Z', '#b45309', { line: '#4a1d05', lw: 1.8 }) + K.stitch('M74 111C88 118 112 118 126 111', '#fde68a', 1.2);
    s += K.part('M114 118L124 140L117 137L111 143L108 120Z', '#b45309', { line: '#4a1d05', lw: 1.6 });
    // проволочная дужка и ботва
    s += K.line('M66 76C56 26 144 26 134 76', '#44403c', 2.8) + K.line('M66 76C56 26 144 26 134 76', '#d6d3d1', 1, { op: 0.7 });
    s += K.leaf(98, 44, 30, -130, '#4d7c0f') + K.leaf(102, 44, 30, -50, '#4d7c0f') + K.leaf(100, 44, 26, -92, '#84cc16');
    // голова-репа
    const head = 'M100 38C124 38 138 54 138 74C138 94 122 106 105 108C103 112 101 116 100 118C99 116 97 112 95 108C78 106 62 94 62 74C62 54 76 38 100 38Z';
    s += K.vol(head, { c1: '#fffaf0', c2: '#d9c7a0', rim: '#ffcf80', rimK: 0.6, tex: false, lw: 2.6, line: '#5a3a1c' });
    s += ceClip(K, head, `<rect x="40" y="30" width="120" height="40" fill="${ceLinA(K, [[0, '#6b21a8', 0.95], [0.55, '#a855f7', 0.7], [1, '#c084fc', 0]], 36, 68)}"/>`);
    s += K.line('M70 62Q68 78 76 94M130 62Q132 78 124 94', '#b8a47a', 1.4, { op: 0.7 });
    s += K.gloss(80, 52, 8, 4, -30, 0.4);
    // свет из прорезей
    s += `<ellipse class="art-blink" cx="100" cy="84" rx="42" ry="30" fill="${K.rad([[0, '#ffb020', 0.3], [1, '#ffb020', 0]])}"/>`;
    const carve = K.rad([[0, '#fffbe6'], [0.45, '#ffd23f'], [1, '#ff6a00']], 0.5, 0.6, 0.7);
    s += `<path d="M74 78L92 78L86 60ZM108 78L126 78L114 60ZM96.5 89L103.5 89L100 82ZM72 92Q100 114 128 92L121 96L114 92L107 97L100 93L93 97L86 92L79 96Z" fill="${carve}" stroke="#6b3a10" stroke-width="2.2" stroke-linejoin="round"/>`;
    // летящие искры
    s += K.spark(170, 92, 3.4, '#ffe08a', 'art-float') + K.spark(26, 60, 3, '#fff3b0', 'art-float') + K.spark(176, 150, 2.6, '#ffd166') + K.spark(24, 150, 2.4, '#ffb347');
    return s;
  },

  // Тюленёк: пятнистый тюлений малыш выглядывает из воды у набережной — огромные тёмные глаза-пуговки, пухлая усатая
  // мордочка, в поднятой ласте — зелёное морское стёклышко; вокруг — круги по воде и пузырьки
  ce_seal(K) {
    const pelt = { c1: '#eef2f7', c2: '#64748b', rim: '#c8f3ff', rimK: 0.7, hiK: 0.25, texK: 0.14, line: '#334155', lw: 2.6 };
    let s = K.aura('#38bdf8', 88, 112, 0.35);
    // левая ласта шлёпает по воде
    s += K.vol('M66 136C56 142 44 150 38 160C44 166 56 164 62 158C68 152 72 146 74 140Z', pelt);
    // тело столбиком
    const body = 'M100 56C126 56 140 76 140 100C140 122 150 142 152 160C154 174 132 182 100 182C68 182 46 174 48 160C50 142 60 122 60 100C60 76 74 56 100 56Z';
    s += K.vol(body, pelt);
    s += [[66, 128, 5, 3.4, -20], [72, 146, 3.6, 2.4, -10], [134, 126, 4.6, 3, 20], [128, 146, 3.4, 2.2, 10], [120, 66, 3.4, 2.2, 20], [80, 66, 2.8, 2, -20], [138, 106, 3, 2, 30], [62, 106, 2.6, 1.8, -30]]
      .map(([x, y, rx, ry, r]) => `<ellipse cx="${x}" cy="${y}" rx="${rx}" ry="${ry}" transform="rotate(${r} ${x} ${y})" fill="#475569" opacity=".5"/>`).join('');
    s += `<ellipse cx="100" cy="146" rx="26" ry="24" fill="${K.rad([[0, '#ffffff', 0.85], [1, '#ffffff', 0]])}"/>`;
    s += K.gloss(78, 72, 10, 5.5, -35, 0.45);
    // глаза-пуговки
    s += K.eyes(100, 92, 17, 12.5, { iris: '#334155', look: [0.05, 0.2] });
    s += K.blush(72, 110, 6) + K.blush(128, 110, 6);
    // усы, щёчки, носик
    s += K.mirror(K.line('M90 112C80 108 70 107 58 109M90 116C80 116 70 118 60 123', '#475569', 1.3));
    s += K.mirror(`<ellipse cx="92.5" cy="113" rx="9" ry="7" fill="${K.lin(['#ffffff', '#dfe6ee'])}" stroke="#64748b" stroke-width="1.4"/><circle cx="89" cy="112" r=".9" fill="#475569"/><circle cx="92.5" cy="115.5" r=".9" fill="#475569"/><circle cx="87.5" cy="116" r=".9" fill="#475569"/>`);
    s += `<path d="M95 103.5Q100 101.5 105 103.5Q104.5 108.5 100 110Q95.5 108.5 95 103.5Z" fill="#1e293b"/><ellipse cx="98" cy="104" rx="1.8" ry="1" fill="#fff" opacity=".7"/>`;
    s += K.mouth('cat', 100, 120, 9);
    // правая ласта с морским стёклышком
    s += K.vol('M136 128C146 120 154 110 158 100C162 94 170 96 168 104C164 116 154 130 142 140Z', pelt);
    s += `<circle class="art-aura" cx="164" cy="92" r="13" fill="${K.rad([[0, '#a7f3d0', 0.8], [1, '#34d399', 0]])}"/>`;
    s += K.part('M156 90L163 84L171 87L172 96L165 101L157 98Z', '#34d399', { line: '#065f46', lw: 1.6, op: 0.92 }) + K.line('M159 90L163 87L166 88', '#ffffff', 1.4);
    // вода по пояс
    const wv = 'M22 160Q32 154 42 160T62 160T82 160T102 160T122 160T142 160T162 160T182 160';
    s += `<path d="${wv}C182 172 146 182 102 182C58 182 22 172 22 160Z" fill="${ceLinA(K, [[0, '#7dd3fc', 0.8], [1, '#0369a1', 0.9]], 154, 182)}"/>`;
    s += K.line(wv, '#e0f7ff', 2.2) + K.line('M40 170Q60 174 80 170M118 172Q140 175 160 169', '#e0f7ff', 1.3, { op: 0.5 });
    s += `<ellipse class="art-blink" cx="100" cy="166" rx="92" ry="16" fill="none" stroke="#e0f7ff" stroke-width="1.2" opacity=".3"/>`;
    s += [[30, 140, 4], [40, 124, 2.6], [172, 130, 3.4], [180, 116, 2.2]].map(([x, y, r], i) => `<circle class="art-float" style="animation-delay:-${i * 0.5}s" cx="${x}" cy="${y}" r="${r}" fill="#e0f7ff" fill-opacity=".25" stroke="#e0f7ff" stroke-width="1.2"/>`).join('');
    s += K.spark(30, 70, 3, '#e0f7ff', 'art-float') + K.spark(150, 40, 2.6, '#c8f3ff');
    return s;
  },

  // Селки: девушка вышла из моря, накинув тюленью шкурку, как плащ с капюшоном: на макушке — сонная мордочка Тюленька,
  // по краям свисают ласты. Тёмные мокрые пряди, огромные тюленьи глаза, платье цвета волны с ракушками по подолу;
  // рукой бережно придерживает край шкурки. Стоит в прибое
  ce_selkie(K) {
    const pelt = { c1: '#d7dee8', c2: '#475569', rim: '#c8f3ff', rimK: 0.6, texK: 0.12, line: '#1e293b', lw: 2.4 };
    const skin = { c1: '#fde7d6', c2: '#e9b596', rim: '#e0f7ff', tex: false, lw: 2.2, line: '#7a4a3a' };
    const hair = { c1: '#5b4636', c2: '#1c120c', rim: '#c8f3ff', rimK: 0.5, tex: false, lw: 2, line: '#120a06' };
    const dressO = { c1: '#5eead4', c2: '#0f766e', rim: '#e0f7ff', rimK: 0.6, texK: 0.25, lw: 2.4, line: '#134e4a' };
    let s = K.aura('#38bdf8', 94, 104, 0.35);
    // шкурка-плащ до земли, на углах — ласты
    s += K.part('M50 154C40 160 34 170 38 176C46 176 54 170 58 162Z', '#64748b', { line: '#1e293b' }) + K.part('M150 154C160 160 166 170 162 176C154 176 146 170 142 162Z', '#64748b', { line: '#1e293b' });
    const cape = 'M100 32C124 32 136 50 136 72C142 98 148 126 152 156C146 162 140 162 136 158L64 158C60 162 54 162 48 156C52 126 58 98 64 72C64 50 76 32 100 32Z';
    s += K.vol(cape, pelt);
    s += [[58, 130], [62, 146], [142, 128], [138, 146], [140, 106], [60, 106]].map(([x, y]) => `<ellipse cx="${x}" cy="${y}" rx="3.4" ry="2.3" fill="#475569" opacity=".5"/>`).join('');
    // мокрые пряди
    s += K.mirror(K.vol('M78 62C68 80 66 104 70 126C74 132 82 132 84 126C82 108 82 88 88 74Z', hair));
    // платье
    const dress = 'M100 92C114 92 122 100 126 112C130 132 136 150 140 170C120 178 80 178 60 170C64 150 70 132 74 112C78 100 86 92 100 92Z';
    s += K.vol(dress, dressO);
    s += K.line('M88 104C84 124 80 146 76 168M112 104C116 124 120 146 124 168', '#134e4a', 1.6, { op: 0.4 });
    s += K.line('M64 160Q100 170 136 160', '#ccfbf1', 2.4, { op: 0.8 });
    const shell = (x, y, r) => `<g transform="translate(${x} ${y}) rotate(${r})"><path d="M-5 2C-6 -4 -2 -7 0 -7C2 -7 6 -4 5 2Z" fill="#fde2e4" stroke="#9f5a6a" stroke-width="1"/><path d="M-2.5 1L-1.5 -5M0 1V-6M2.5 1L1.5 -5" stroke="#c98a98" stroke-width=".8"/></g>`;
    s += shell(78, 156, -8) + shell(100, 160, 0) + shell(122, 156, 8);
    // полы шкурки спереди: левая свободно спадает, правую рука подтягивает к груди
    s += K.vol('M76 66C68 90 64 124 60 162C66 166 72 164 76 160C76 128 80 100 88 82Z', { ...pelt, texK: 0.1 });
    s += K.vol('M124 66C132 90 132 106 126 116C120 118 114 116 112 112C116 100 116 88 112 80Z', { ...pelt, texK: 0.1 });
    s += `<ellipse cx="68" cy="130" rx="2.6" ry="1.8" fill="#475569" opacity=".5"/><ellipse cx="124" cy="96" rx="2.6" ry="1.8" fill="#475569" opacity=".5"/>`;
    s += K.vol('M132 104C136 112 132 120 124 122C120 120 118 116 120 112Z', { ...dressO, tex: false, lw: 2 });
    s += K.vol(K.ell(118, 114, 6, 5.5), skin);
    // лицо и чёлка на пробор
    s += K.vol(K.ell(100, 78, 19.5, 19.5), skin);
    s += K.part('M81 78C78 62 87 54 100 54C113 54 122 62 119 78C116 70 109 64 101 63C98 68 90 72 81 78Z', '#3b2a1e', { line: '#120a06', lw: 1.6 });
    // капюшон — голова тюленя с сонной мордочкой
    s += K.vol('M74 70C70 46 84 28 100 28C116 28 130 46 126 70C120 58 110 52 100 52C90 52 80 58 74 70Z', pelt);
    s += K.closed(100, 37, 8, 3.6, false);
    s += `<ellipse cx="100" cy="44" rx="3" ry="2.2" fill="#1e293b"/><circle cx="94" cy="46" r=".8" fill="#475569"/><circle cx="106" cy="46" r=".8" fill="#475569"/>`;
    s += K.gloss(84, 38, 6, 3, -30, 0.4);
    // глаза, как у тюленя
    s += K.eyes(100, 82, 9.4, 8.8, { iris: '#334155', lash: true, look: [0, 0.2] });
    s += K.blush(85, 91, 4.4) + K.blush(115, 91, 4.4) + K.mouth('smile', 100, 92, 8);
    // прибой
    const wv = 'M24 168Q34 162 44 168T64 168T84 168T104 168T124 168T144 168T164 168T184 168';
    s += `<path d="${wv}C184 176 148 184 104 184C60 184 24 176 24 168Z" fill="${ceLinA(K, [[0, '#a5f3fc', 0.7], [1, '#0e7490', 0.85]], 162, 184)}"/>`;
    s += K.line(wv, '#f0fdff', 2.2);
    s += [[36, 162], [70, 162], [132, 163], [166, 161]].map(([x, y], i) => `<circle class="art-blink" style="animation-delay:-${i * 0.4}s" cx="${x}" cy="${y}" r="2" fill="#f0fdff"/>`).join('');
    s += K.spark(28, 70, 3, '#e0f7ff', 'art-float') + K.spark(170, 60, 2.6, '#c8f3ff', 'art-float') + K.spark(174, 100, 2.2, '#e0f7ff');
    return s;
  },

  // Мерроу: ирландская морская дева сидит на камне, поросшем водорослями, и поёт перед штормом. На голове — красная
  // шапочка из перьев (без неё не нырнуть), волосы цвета волны развеваются, чешуйчатый хвост огибает камень,
  // в поднятой руке — серебряный гребень; вокруг — нотки и пена прибоя
  ce_merrow(K) {
    const skin = { c1: '#fde9dc', c2: '#e3ae94', rim: '#e0f7ff', tex: false, lw: 2.2, line: '#7a4a3a' };
    const tailO = { c1: '#6ee7d6', c2: '#0f766e', rim: '#e0f7ff', rimK: 0.65, texK: 0.2, lw: 2.4, line: '#0b3d36' };
    const hair = { c1: '#7ff0c8', c2: '#0f766e', rim: '#e0f7ff', tex: false, lw: 2.2, line: '#0b3d36' };
    let s = K.aura('#2dd4bf', 96, 100, 0.4);
    // волосы сзади развеваются
    s += K.vol('M84 50C62 56 54 80 54 104C54 124 44 140 28 150C46 154 62 146 70 134C76 120 78 102 82 88Z', hair);
    s += K.vol('M116 50C134 56 142 74 144 94C146 108 152 118 162 124C148 128 136 120 132 108C130 96 126 84 118 76Z', hair);
    s += K.line('M72 70C62 90 62 116 50 140M134 72C138 90 140 104 150 118', '#ccfbf1', 1.4, { op: 0.6 });
    // камень с водорослями
    s += K.vol('M36 180C34 164 44 152 60 150C70 142 90 142 102 148C116 144 132 150 138 162C144 170 142 176 140 180Z', { c1: '#a3b1c2', c2: '#334155', rim: '#c8f3ff', tex: false, lw: 2.4, line: '#1e293b' });
    s += K.line('M46 170C40 160 48 152 44 142M54 166C58 156 52 150 58 142M132 170C138 162 132 156 138 150', '#166534', 3.2) + K.line('M46 170C40 160 48 152 44 142M54 166C58 156 52 150 58 142M132 170C138 162 132 156 138 150', '#4ade80', 1.3);
    // плавник и хвост
    const finF = K.lin(['#ccfbf1', '#5eead4', '#0d9488'], 0, 0, 1, 1);
    s += `<path d="M158 124C154 108 160 94 174 86C172 98 174 106 184 112C174 116 166 118 158 124Z" fill="${finF}" stroke="#0b3d36" stroke-width="2" stroke-linejoin="round"/>`;
    s += `<path d="M158 124C170 114 184 114 194 120C186 124 180 130 178 140C172 132 166 128 158 124Z" fill="${finF}" stroke="#0b3d36" stroke-width="2" stroke-linejoin="round"/>`;
    s += K.line('M160 120L172 94M162 120L180 108M162 124L188 120M162 126L178 134', '#0f766e', 1, { op: 0.7 });
    const tail = 'M82 126C78 146 90 164 112 166C132 168 146 158 152 146C156 138 158 130 162 122C158 132 150 144 138 148C126 152 116 148 116 136C116 132 118 128 118 126Z';
    s += K.vol(tail, tailO);
    let sc = '';
    for (let r = 0; r < 8; r++) for (let x = 70 + (r % 2) * 3.5; x < 166; x += 7) sc += `M${x} ${128 + r * 6}q3.5 4 7 0`;
    s += ceClip(K, tail, K.line(sc, '#ccfbf1', 1.1, { op: 0.6 }));
    // левая рука на камне
    s += K.vol('M84 98C74 104 68 118 66 136C68 142 76 142 78 136C78 124 82 112 88 106Z', skin);
    s += K.vol(K.ell(71, 140, 6.5, 5), skin);
    // тело, чешуйчатый пояс и лиф с жемчугом
    s += K.vol('M100 86C112 86 119 94 120 104C121 114 117 122 115 130L85 130C83 122 79 114 80 104C81 94 88 86 100 86Z', skin);
    s += K.part('M83 118Q100 128 117 118L119 132Q100 140 81 132Z', '#2dd4bf', { line: '#0b3d36', lw: 1.8 }) + K.line('M86 126Q100 133 114 126', '#ccfbf1', 1.2, { op: 0.7 });
    s += K.part('M81 100C90 95 110 95 119 100L120 111C110 107 90 107 80 111Z', '#0d9488', { line: '#0b3d36', lw: 1.6 });
    for (let i = 0; i < 7; i++) s += `<circle cx="${84 + i * 5.3}" cy="${K.f(100 - Math.sin(i / 6 * Math.PI) * 2)}" r="1.8" fill="#fff8f0" stroke="#9f7a6a" stroke-width=".6"/>`;
    // правая рука с серебряным гребнем
    s += K.vol('M116 98C126 94 134 86 138 76C144 74 148 80 145 86C140 96 130 104 120 108Z', skin);
    s += K.part('M134 58H158V65H134Z', '#e2e8f0', { line: '#475569', lw: 1.6 });
    s += K.line('M137 58V50M141 58V50M145 58V50M149 58V50M153 58V50M157 58V51', '#cbd5e1', 1.8) + K.spark(158, 50, 3, '#ffffff');
    s += K.vol(K.ell(142, 70, 6, 6.5), skin);
    // голова
    s += K.vol(K.ell(100, 66, 18, 19), skin);
    s += K.part('M82 66C80 52 88 44 100 44C112 44 120 52 118 66C114 58 108 54 100 56C94 58 88 58 84 62Z', '#34d399', { line: '#0b3d36', lw: 1.6 });
    // красная шапочка с перьями
    const feather = (x, y, r, c) => `<g transform="translate(${x} ${y}) rotate(${r}) scale(.72)"><path d="M0 0C-5 -8 -5 -20 0 -28C5 -20 5 -8 0 0Z" fill="${K.lin([K.shade(c, 0.3), c])}" stroke="#7f1d1d" stroke-width="1.3"/><path d="M0 -2V-24" stroke="#fee2e2" stroke-width=".9"/></g>`;
    s += feather(112, 40, 22, '#fb923c') + feather(114, 42, 48, '#ef4444') + feather(114, 45, 74, '#f87171');
    s += K.vol('M80 54C78 40 88 32 100 32C112 32 122 40 120 54C110 48 90 48 80 54Z', { c1: '#f87171', c2: '#991b1b', rim: '#fecaca', tex: false, lw: 2.2, line: '#5f0f0f' });
    s += K.stitch('M82 51C92 46 108 46 118 51', '#fde68a', 1.4);
    // лицо: поёт, глядя на небо
    s += K.eyes(100, 68, 8, 6.4, { iris: '#0d9488', lash: true, look: [0.3, -0.4] });
    s += K.blush(87, 76, 3.8) + K.blush(113, 76, 3.8) + K.mouth('open', 100, 78, 9);
    // нотки песни и пена
    s += ceNote(40, 64, 1, '#ccfbf1', '-0.4s') + ceNote(172, 60, 0.85, '#a5f3fc', '-1.2s') + ceNote(160, 30, 0.7, '#ccfbf1', '-0.8s');
    s += K.line('M20 176Q30 170 40 176M146 178Q158 172 170 178Q178 174 186 178', '#f0fdff', 2.2, { op: 0.8 });
    s += K.spark(24, 100, 3, '#e0f7ff', 'art-float') + K.spark(186, 150, 2.6, '#ccfbf1');
    return s;
  },

  // Клеверок: круглый клеверный дух с большим трилистником на макушке (на листке сидит божья коровка), на пузике — светлая
  // «галочка», как у настоящего клевера. В поднятой ручке гордо держит найденный четырёхлистник; вокруг — шарики клевера
  ce_clover(K) {
    const f = K.f, g = { c1: '#a7f3c0', c2: '#16a34a', rim: '#e4ffb0', rimK: 0.6, texK: 0.16, lw: 2.6, line: '#14532d' };
    let s = K.aura('#4ade80', 90, 116, 0.4);
    // шарики цветущего клевера
    const bloom = (x, y, r) => K.line(`M${x} ${y + r}v14`, '#15803d', 2) + `<circle cx="${x}" cy="${y}" r="${r}" fill="${K.rad([[0, '#ffffff'], [0.7, '#fce7f3'], [1, '#f9a8d4']])}" stroke="#9d4b73" stroke-width="1.2"/>` +
      K.line(`M${f(x - r * 0.5)} ${f(y - r * 0.2)}l${f(r * 0.25)} ${f(r * 0.5)}M${x} ${f(y - r * 0.5)}v${f(r * 0.6)}M${f(x + r * 0.5)} ${f(y - r * 0.2)}l${f(-r * 0.25)} ${f(r * 0.5)}`, '#f472b6', 1, { op: 0.8 });
    s += bloom(30, 158, 8) + bloom(170, 154, 9) + bloom(152, 170, 6);
    // ножки
    s += K.mirror(K.vol(K.ell(80, 172, 14, 8), { ...g, tex: false, lw: 2.2 }));
    // левая ручка на пузике
    s += K.vol('M52 128C44 134 42 146 48 152C54 154 60 150 62 144Z', g);
    // тело
    s += K.vol('M100 80C140 80 158 106 156 134C154 162 132 176 100 176C68 176 46 162 44 134C42 106 60 80 100 80Z', g);
    s += K.line('M66 160Q100 134 134 160', '#ecfccb', 7, { op: 0.35 });
    s += K.gloss(72, 100, 10, 5.5, -40, 0.45);
    // трилистник на макушке с божьей коровкой
    s += ceShamrock(K, 100, 54, 21, 0, '#22c55e');
    s += `<g transform="rotate(-20 104 34)"><ellipse cx="104" cy="34" rx="5" ry="4.2" fill="${K.lin(['#fca5a5', '#dc2626'])}" stroke="#450a0a" stroke-width="1.2"/><path d="M104 30V38" stroke="#450a0a" stroke-width="1"/><circle cx="101.5" cy="33" r="1" fill="#1c1917"/><circle cx="106.5" cy="35" r="1" fill="#1c1917"/><circle cx="104" cy="29.6" r="2" fill="#1c1917"/></g>`;
    // мордочка
    s += K.eyes(100, 122, 22, 13.5, { iris: '#15803d', look: [0.2, 0.1] });
    s += K.blush(70, 140, 7) + K.blush(130, 140, 7) + K.mouth('smile', 100, 142, 16);
    // правая ручка с четырёхлистником
    s += K.vol('M146 124C154 116 160 106 162 96C166 90 172 92 172 98C170 110 162 124 152 134Z', g);
    s += `<circle class="art-aura" cx="168" cy="76" r="18" fill="${K.rad([[0, '#fef9c3', 0.9], [1, '#facc15', 0]])}"/>`;
    s += ceShamrock(K, 168, 76, 10, 12, '#16a34a', true);
    s += K.vol(K.ell(167, 94, 5.5, 5), { ...g, tex: false, lw: 2 });
    s += K.spark(186, 58, 3.4, '#fef9c3') + K.spark(150, 56, 2.6, '#fde68a', 'art-float') + K.spark(24, 96, 3, '#fef9c3', 'art-float') + K.spark(40, 60, 2.2, '#e4ffb0');
    return s;
  },

  // Лепрекон: сапожник волшебного народа — зелёный сюртук, кожаный фартук, высокая шляпа с пряжкой и трилистником,
  // рыжая борода-шкиперка. В поднятой руке молоточек, в другой — единственный башмачок (пару он не шьёт никогда).
  // За спиной радуга, а в её конце — горшок с золотом
  ce_leprechaun(K) {
    const f = K.f;
    const coat = { c1: '#4ade80', c2: '#14532d', rim: '#e4ffb0', rimK: 0.55, texK: 0.14, lw: 2.4, line: '#0b2e17' };
    const skin = { c1: '#fde0c8', c2: '#e3a580', rim: '#fff3d6', tex: false, lw: 2.2, line: '#7a4a2a' };
    const black = { c1: '#4b5563', c2: '#0b0f19', rim: '#e4ffb0', rimK: 0.4, tex: false, lw: 2, line: '#000000' };
    let s = K.aura('#facc15', 90, 110, 0.35);
    // радуга
    ['#ef4444', '#f97316', '#facc15', '#22c55e', '#3b82f6', '#8b5cf6'].forEach((c, i) => {
      const r = 82 - i * 5.5;
      s += `<path d="M${f(100 - r)} 166A${r} ${r} 0 0 1 ${f(100 + r)} 166" fill="none" stroke="${c}" stroke-width="5.8" opacity=".5"/>`;
    });
    s += K.part('M12 170C10 162 18 158 24 162C26 154 38 154 40 162C46 160 52 166 48 172H14Z', '#f8fafc', { line: '#cbd5e1', lw: 1.6 });
    // горшок с золотом
    s += `<circle class="art-aura" cx="168" cy="150" r="24" fill="${K.rad([[0, '#fef08a', 0.8], [1, '#facc15', 0]])}"/>`;
    const coin = (x, y) => `<ellipse cx="${x}" cy="${y}" rx="5.4" ry="3.4" fill="${K.lin(['#fef08a', '#eab308'])}" stroke="#854d0e" stroke-width="1.1"/>`;
    s += [[156, 150], [164, 146], [172, 148], [180, 150], [160, 144], [168, 141], [176, 143], [170, 137]].map(([x, y]) => coin(x, y)).join('');
    s += K.vol('M148 152C146 166 154 178 168 180C184 178 192 166 190 152Z', black);
    s += `<ellipse cx="169" cy="152" rx="22" ry="5" fill="#374151" stroke="#000" stroke-width="2"/>`;
    s += K.spark(186, 128, 3.4, '#fef9c3') + K.spark(158, 132, 2.6, '#fef08a', 'art-float');
    // ноги: чулки и башмаки с пряжками
    s += K.part('M73 156H84V172H73Z', '#f8fafc', { line: '#64748b', lw: 1.6 }) + K.part('M92 156H103V172H92Z', '#f8fafc', { line: '#64748b', lw: 1.6 });
    s += K.vol('M64 172C64 166 74 164 84 168C88 170 88 176 86 179H64Z', black) + K.vol('M112 172C112 166 102 164 92 168C88 170 88 176 90 179H112Z', black);
    s += `<rect x="75" y="168" width="6" height="5" rx="1" fill="none" stroke="#facc15" stroke-width="1.6"/><rect x="95" y="168" width="6" height="5" rx="1" fill="none" stroke="#facc15" stroke-width="1.6"/>`;
    // сюртук, фартук, пояс
    s += K.vol('M88 96C108 96 120 108 124 124C128 140 128 152 124 162C112 168 64 168 52 162C48 152 48 140 52 124C56 108 68 96 88 96Z', coat);
    s += K.part('M74 122H102L106 160H70Z', '#a16207', { line: '#451a03', lw: 1.8 }) + K.stitch('M76 125H100L103 157H73Z', '#fde68a', 1.1);
    s += K.part('M53 128Q88 136 123 128L124 136Q88 144 52 136Z', '#1f2937', { line: '#000', lw: 1.6 });
    s += `<rect x="82" y="131" width="12" height="9" rx="1.5" fill="none" stroke="#facc15" stroke-width="2.2"/>`;
    s += [[60, 112], [60, 150], [116, 112], [116, 150]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="2.4" fill="#facc15" stroke="#854d0e" stroke-width=".9"/>`).join('');
    // левая рука с одним башмачком
    s += K.vol('M62 104C52 110 44 120 42 132C46 138 54 138 56 132C58 124 62 118 68 114Z', coat);
    s += K.vol('M22 146C22 140 30 138 38 141C44 143 46 148 44 152H22Z', black) + `<rect x="31" y="141" width="5" height="4" rx="1" fill="none" stroke="#facc15" stroke-width="1.4"/>`;
    s += K.vol(K.ell(46, 136, 6.5, 6), skin);
    // правая рука с молоточком
    s += K.line('M138 82L148 54', '#451a03', 5.6) + K.line('M138 82L148 54', '#b45309', 2.8);
    s += K.part('M138 50L156 56L153 64L136 58Z', '#cbd5e1', { line: '#334155', lw: 1.8 });
    s += K.vol('M112 104C122 100 130 92 132 82C136 78 142 80 142 86C140 98 130 110 118 116Z', coat);
    s += K.vol(K.ell(138, 82, 6.5, 6), skin);
    // голова, рыжая борода
    s += K.part(K.ell(69, 78, 4.5, 6), '#f0b890', { line: '#7a4a2a' }) + K.part(K.ell(107, 78, 4.5, 6), '#f0b890', { line: '#7a4a2a' });
    s += K.vol(K.ell(88, 76, 19, 18), skin);
    s += K.vol('M68 72C66 92 74 108 88 110C102 108 110 92 108 72C104 84 96 90 88 90C80 90 72 84 68 72Z', { c1: '#fb923c', c2: '#b4400c', rim: '#ffd9a0', tex: false, lw: 2, line: '#6a2406' });
    s += K.line('M74 88q2 8 6 12M88 94v10M102 88q-2 8 -6 12', '#9a3412', 1.4, { op: 0.8 });
    s += K.eyes(88, 74, 8, 5.6, { iris: '#15803d', look: [0.5, 0] });
    s += `<ellipse cx="88" cy="82" rx="4.6" ry="3.8" fill="#f4a582" stroke="#7a3a24" stroke-width="1.4"/>` + K.blush(76, 83, 3.6) + K.blush(100, 83, 3.6);
    s += `<path d="M82 90Q88 96 94 90Q88 92 82 90Z" fill="#6b1d2a" stroke="${K.INK}" stroke-width="1.8" stroke-linejoin="round"/>`;
    // шляпа с пряжкой и трилистником
    let h = K.vol('M70 60L74 22C82 17 100 17 108 22L110 60Z', coat);
    h += `<ellipse cx="90" cy="60" rx="30" ry="6.5" fill="${K.lin(['#22c55e', '#14532d'])}" stroke="#0b2e17" stroke-width="2.2"/>`;
    h += K.part('M71 48H109L110 58H70Z', '#1f2937', { line: '#000', lw: 1.6 }) + `<rect x="84" y="47" width="11" height="11" rx="1.5" fill="none" stroke="#facc15" stroke-width="2.4"/>`;
    h += ceShamrock(K, 104, 46, 6.5, 20, '#86efac');
    h += K.gloss(80, 30, 4, 2.4, -20, 0.4);
    s += K.g(h, 'rotate(-8 90 60)');
    s += K.spark(20, 110, 2.8, '#fef9c3', 'art-float') + K.spark(128, 30, 2.4, '#fef08a');
    return s;
  },

  // Король Иубдан: подросший Лепрекон стал королём крошечного народа — гордо выпятил грудь и задрал нос. На высокой зелёной
  // шляпе — золотая корона, алая мантия с горностаем, рыжая борода заплетена в косы с бусинами, пояс с трикветром,
  // в руке — скипетр с четырёхлистником. Стоит на стопке золотых монет, за спиной — радуга-нимб
  ce_iubdan(K) {
    const f = K.f;
    const skin = { c1: '#fde0c8', c2: '#e3a580', rim: '#fff3d6', tex: false, lw: 2.2, line: '#7a4a2a' };
    const green = { c1: '#4ade80', c2: '#14532d', rim: '#e4ffb0', rimK: 0.55, texK: 0.14, lw: 2.4, line: '#0b2e17' };
    const red = { c1: '#f87171', c2: '#7f1d1d', rim: '#fde68a', rimK: 0.55, tex: false, lw: 2.4, line: '#450a0a' };
    let s = K.aura('#facc15', 96, 100, 0.45);
    // радуга-нимб
    ['#ef4444', '#f97316', '#facc15', '#22c55e', '#3b82f6', '#8b5cf6'].forEach((c, i) => {
      const r = 74 - i * 5;
      s += `<path d="M${f(100 - r)} 112A${r} ${r} 0 0 1 ${f(100 + r)} 112" fill="none" stroke="${c}" stroke-width="5" opacity=".5"/>`;
    });
    // мантия
    s += K.vol('M100 72C128 74 146 94 152 120C158 142 160 152 158 160C140 164 60 164 42 160C40 152 42 142 48 120C54 94 72 74 100 72Z', red);
    s += K.line('M44 158C54 160 146 160 156 158', '#f8fafc', 6) + [52, 70, 88, 106, 124, 142].map(x => `<path d="M${x} 157l1.4 3l1.4 -3z" fill="#1c1917"/>`).join('');
    s += K.stitch('M50 150C60 152 140 152 150 150', '#fde68a', 1.4);
    // стопка монет
    for (let i = 0; i < 4; i++) {
      const y = 178 - i * 5.5;
      s += `<path d="M64 ${y}v4.5a36 6 0 0 0 72 0v-4.5" fill="#a16207" stroke="#713f12" stroke-width="1.4"/><ellipse cx="100" cy="${y}" rx="36" ry="6" fill="${K.lin(['#fef08a', '#eab308'])}" stroke="#713f12" stroke-width="1.4"/>`;
    }
    s += [[40, 176], [158, 178], [168, 172]].map(([x, y]) => `<ellipse cx="${x}" cy="${y}" rx="6" ry="3.6" fill="${K.lin(['#fef08a', '#eab308'])}" stroke="#713f12" stroke-width="1.2"/>`).join('');
    // сапожки
    s += K.mirror(K.vol('M78 162C78 156 88 154 96 157C99 159 99 163 98 166H78Z', { c1: '#7c4a1d', c2: '#2a1206', tex: false, lw: 2, line: '#1c0a02' }));
    // кафтан, пояс с трикветром
    s += K.vol('M100 96C118 96 128 108 130 124C132 140 130 152 126 162L74 162C70 152 68 140 70 124C72 108 82 96 100 96Z', green);
    s += K.part('M71 136Q100 144 129 136L130 145Q100 153 70 145Z', '#854d0e', { line: '#451a03', lw: 1.6 });
    s += `<circle cx="100" cy="143" r="7" fill="${K.lin(['#fef08a', '#ca8a04'])}" stroke="#713f12" stroke-width="1.6"/>` + ceTriquetra(K, 100, 143.5, 5, '#713f12', 1.2);
    s += K.stitch('M100 150V160', '#fde68a', 1.4);
    // левая рука в бок
    s += K.vol('M74 108C62 112 56 124 58 134C62 140 70 140 72 134C72 126 74 120 78 116Z', green) + K.vol(K.ell(66, 136, 6, 5.5), skin);
    // горностаевый воротник
    s += K.part('M72 96C82 104 118 104 128 96C132 100 132 106 128 110C116 116 84 116 72 110C68 106 68 100 72 96Z', '#f8fafc', { line: '#94a3b8', lw: 1.6 });
    s += [80, 92, 108, 120].map(x => `<path d="M${x} 106l1.4 3l1.4 -3z" fill="#1c1917"/>`).join('');
    // голова и нос кверху
    s += K.vol(K.ell(100, 76, 19, 18), skin);
    // борода, заплетённая в косы
    s += K.vol('M80 76C78 96 84 112 94 120L100 114L106 120C116 112 122 96 120 76C114 88 106 92 100 92C94 92 86 88 80 76Z', { c1: '#fb923c', c2: '#b4400c', rim: '#ffd9a0', tex: false, lw: 2, line: '#6a2406' });
    s += K.mirror(K.line('M92 100l4 4M90 106l4 4M92 112l3 3', '#9a3412', 1.4) + `<circle cx="94" cy="122" r="2.6" fill="#facc15" stroke="#854d0e" stroke-width="1"/>`);
    s += K.eyes(100, 72, 8, 5.6, { iris: '#15803d', lid: 'half', skin: '#f2c2a0', look: [-0.2, -0.6] });
    s += `<path d="M96 82Q100 74 106 80Q104 84 98 85Z" fill="#f4a582" stroke="#7a3a24" stroke-width="1.4" stroke-linejoin="round"/>` + K.blush(86, 82, 3.6) + K.blush(114, 82, 3.6);
    s += K.line('M94 90Q100 93 106 89', K.INK, 2);
    // шляпа и корона
    s += K.vol('M82 58L85 20C92 15 108 15 115 20L118 58Z', green);
    s += K.gloss(92, 28, 3.6, 2.2, -20, 0.4);
    s += K.part('M78 60L80 42L88 50L94 36L100 48L106 36L112 50L120 42L122 60Q100 55 78 60Z', '#facc15', { line: '#854d0e', lw: 1.6 });
    s += K.rhomb(100, 52, 3, '#22c55e', '#14532d') + `<circle cx="94" cy="36" r="2" fill="#f8fafc"/><circle cx="106" cy="36" r="2" fill="#f8fafc"/><circle cx="80" cy="42" r="1.8" fill="#ef4444"/><circle cx="120" cy="42" r="1.8" fill="#ef4444"/>`;
    // правая рука со скипетром
    s += K.line('M140 162L146 58', '#713f12', 5.4) + K.line('M140 162L146 58', '#facc15', 2.8);
    s += `<circle class="art-aura" cx="146" cy="46" r="18" fill="${K.rad([[0, '#fef9c3', 0.9], [1, '#4ade80', 0]])}"/>`;
    s += `<circle cx="146" cy="46" r="11" fill="none" stroke="#facc15" stroke-width="2.4"/>` + ceShamrock(K, 146, 46, 8, 0, '#22c55e', true);
    s += K.vol('M126 108C136 112 142 118 144 126C140 132 134 132 130 128C128 122 124 118 120 116Z', green) + K.vol(K.ell(142, 128, 6, 5.5), skin);
    s += K.spark(28, 70, 3.4, '#fef9c3', 'art-float') + K.spark(176, 96, 3, '#fde68a') + K.spark(34, 130, 2.6, '#fef08a') + K.spark(170, 22, 2.6, '#fef9c3', 'art-float');
    return s;
  },

  // Пикси: крошечная корнуоллская фея — шапочка из колокольчика наперстянки с крапинками, острые ушки, стрекозиные крылышки,
  // озорная улыбка. Катается на завитке сквозняка и держит пушистый одуванчик — вот-вот дунет, и семена уже летят
  ce_pixie(K) {
    const f = K.f, b = { c1: '#e0e7ff', c2: '#6d74e8', rim: '#eef0ff', rimK: 0.65, texK: 0.22, lw: 2.6, line: '#2e2a7a' };
    let s = K.aura('#a5b4fc', 90, 112, 0.4);
    // сквозняк-завиток
    const sw = 'M26 168C50 186 150 186 170 160C182 144 168 126 152 132C140 138 146 154 158 150';
    s += K.line(sw, '#c7d2fe', 10, { op: 0.35 }) + K.line(sw, '#ffffff', 3);
    s += K.line('M14 150C28 146 40 150 50 158M150 176C164 178 176 174 186 166', '#ffffff', 2, { op: 0.6, cls: 'art-float' });
    // стрекозиные крылышки
    const wf = K.lin(['#f5f3ff', '#c7d2fe', '#a5f3fc'], 0, 0, 1, 1);
    const wing = `<g class="art-wing"><path d="M84 108C64 88 40 76 22 80C16 84 24 96 40 102C56 108 72 110 84 112Z" fill="${wf}" fill-opacity=".8" stroke="#6366f1" stroke-width="1.6" stroke-linejoin="round"/>` +
      `<path d="M84 118C68 122 50 132 40 146C38 154 50 154 62 144C72 136 80 128 86 122Z" fill="${wf}" fill-opacity=".75" stroke="#6366f1" stroke-width="1.6" stroke-linejoin="round"/>` +
      K.line('M84 110C66 98 44 86 26 84M60 104L54 92M44 98L40 88M84 120C68 130 54 140 44 148M66 132L58 128', '#818cf8', 1, { op: 0.8 }) + '</g>';
    s += K.g(K.mirror(wing), 'translate(0 -22)');
    // острые ушки и ножки
    s += K.mirror(K.vol('M60 122C50 118 40 112 32 104C44 102 56 106 64 112Z', { c1: '#f5f3ff', c2: '#a5b4fc', rim: '#ffffff', tex: false, lw: 2.2, line: '#2e2a7a' }));
    s += K.mirror(K.vol(K.ell(86, 170, 8, 6), { ...b, tex: false, lw: 2 }));
    // левая ручка держится за ветер
    s += K.vol('M58 136C50 142 46 150 48 158C52 162 58 160 60 154Z', b);
    // тело
    s += K.vol('M100 86C130 86 146 106 146 130C146 154 128 168 100 168C72 168 54 154 54 130C54 106 70 86 100 86Z', b);
    s += K.gloss(72, 110, 8, 4.5, -40, 0.4);
    // шапочка — колокольчик наперстянки
    s += K.vol('M64 100C62 72 78 48 100 44C122 48 138 72 136 100C128 96 122 100 116 96C110 100 104 96 100 100C96 96 90 100 84 96C78 100 72 96 64 100Z', { c1: '#f5b0f7', c2: '#a21caf', rim: '#fde7ff', tex: false, lw: 2.4, line: '#5b0b63' });
    s += K.line('M78 62Q72 80 74 96M100 48V96M122 62Q128 80 126 96', '#86198f', 1.4, { op: 0.45 });
    s += [[76, 90], [90, 93], [110, 93], [124, 90], [84, 83], [116, 83]].map(([x, y]) => `<circle cx="${x}" cy="${y}" r="2" fill="#6b0f73"/><circle cx="${x}" cy="${y}" r="3.2" fill="none" stroke="#fff" stroke-width=".9" opacity=".7"/>`).join('');
    s += K.line('M100 45C100 35 106 27 116 27', '#3f6212', 3) + K.leaf(114, 28, 16, -20, '#65a30d');
    s += K.gloss(82, 62, 7, 3.6, -40, 0.45);
    // мордочка
    s += K.eyes(100, 126, 20, 12.5, { iris: '#7c3aed', look: [0.45, 0.05] });
    s += K.blush(72, 142, 6) + K.blush(128, 142, 6) + K.mouth('cat', 100, 144, 14);
    // правая ручка с одуванчиком
    s += K.line('M158 116C160 102 160 90 158 76', '#4d7c0f', 2.2);
    let puff = `<circle cx="158" cy="66" r="15" fill="${K.rad([[0, '#ffffff', 0.7], [1, '#e0e7ff', 0.1]])}"/>`;
    for (let i = 0; i < 18; i++) {
      const a = i * 20 * Math.PI / 180, x = 158 + 14 * Math.cos(a), y = 66 + 14 * Math.sin(a);
      puff += K.line(`M158 66L${f(x)} ${f(y)}`, '#ffffff', 0.8, { op: 0.8 }) + `<circle cx="${f(x)}" cy="${f(y)}" r="1.6" fill="#ffffff"/>`;
    }
    s += puff + `<circle cx="158" cy="66" r="2.6" fill="#a3a36b"/>`;
    const seed = (x, y, r, d) => `<g class="art-float" style="animation-delay:${d}s"><g transform="rotate(${r} ${x} ${y})">${K.line(`M${x} ${y}v8`, '#ffffff', 0.9)}<path d="M${x - 4} ${y}Q${x} ${y - 4} ${x + 4} ${y}" stroke="#ffffff" stroke-width="1" fill="none"/><circle cx="${x}" cy="${y + 8}" r="1" fill="#a3a36b"/></g></g>`;
    s += seed(184, 44, 20, -0.3) + seed(178, 24, 35, -1.1) + seed(188, 82, 10, -0.7);
    s += K.vol('M140 138C148 132 152 124 154 118C158 114 164 116 162 122C160 130 154 140 146 146Z', b) + K.vol(K.ell(158, 118, 5.5, 5), { ...b, tex: false, lw: 2 });
    s += K.spark(30, 50, 3, '#ffffff', 'art-float') + K.spark(60, 26, 2.4, '#e0e7ff') + K.spark(24, 118, 2.2, '#f0abfc');
    return s;
  },

  // Фея холмов: из народа ши — тоненькая фея кружится в танце посреди грибного круга на газоне. Крылья-бабочки с «глазками»,
  // юбка из лепестков раскрутилась колоколом, волосы цвета мяты с венком, острые ушки; танцует на цыпочках, зажмурившись
  ce_sidhe(K) {
    const f = K.f;
    const skin = { c1: '#fdeee4', c2: '#e8b8a0', rim: '#eef0ff', tex: false, lw: 2, line: '#7a4a3a' };
    const hair = { c1: '#d1fae5', c2: '#34d399', rim: '#ffffff', tex: false, lw: 2, line: '#0f5f45' };
    let s = K.aura('#a5b4fc', 94, 104, 0.4) + K.aura('#a7f3d0', 60, 160, 0.3);
    // грибной круг
    const shroom = (x, y, k) => `<g transform="translate(${x} ${y}) scale(${k})"><path d="M-3 0V-8H3V0Z" fill="#fef3c7" stroke="#7c2d12" stroke-width="1.4"/>` +
      `<path d="M-9 -7C-9 -16 9 -16 9 -7Z" fill="${K.lin(['#fca5a5', '#dc2626'])}" stroke="#7c2d12" stroke-width="1.4"/><circle cx="-4" cy="-10" r="1.4" fill="#fff"/><circle cx="2" cy="-12" r="1.2" fill="#fff"/><circle cx="5" cy="-9" r="1" fill="#fff"/></g>`;
    const ring = a => [f(100 + 76 * Math.cos(a * Math.PI / 180)), f(168 + 12 * Math.sin(a * Math.PI / 180))];
    s += `<ellipse cx="100" cy="168" rx="76" ry="12" fill="none" stroke="#bbf7d0" stroke-width="2" opacity=".45"/>`;
    for (const a of [200, 230, 260, 290, 320, 345]) { const [x, y] = ring(a); s += shroom(x, y, 0.75); }
    // крылья-бабочки
    const wf = K.lin(['#f5f3ff', '#c4b5fd', '#a7f3d0'], 0, 0, 1, 1);
    const wing = `<g class="art-wing"><path d="M96 96C80 70 50 54 34 64C24 72 32 96 56 104C70 108 86 106 96 102Z" fill="${wf}" fill-opacity=".85" stroke="#6366f1" stroke-width="1.8" stroke-linejoin="round"/>` +
      `<path d="M96 106C80 112 62 128 62 144C64 154 78 152 88 138C94 128 96 118 96 106Z" fill="${wf}" fill-opacity=".8" stroke="#6366f1" stroke-width="1.8" stroke-linejoin="round"/>` +
      `<circle cx="52" cy="80" r="7" fill="#f0abfc" opacity=".8"/><circle cx="52" cy="80" r="3.4" fill="#6366f1"/><circle cx="76" cy="136" r="4.6" fill="#f0abfc" opacity=".8"/>` +
      K.line('M96 100C80 88 60 76 42 70M96 104C80 100 64 100 50 98M96 110C86 122 76 134 68 144', '#818cf8', 1, { op: 0.7 }) + '</g>';
    s += K.mirror(wing);
    // волосы развеваются в танце
    s += K.vol('M88 56C72 62 64 80 66 100C66 116 58 128 48 136C62 138 74 130 80 118C82 104 84 90 90 78Z', hair);
    s += K.vol('M112 56C130 58 146 68 160 82C152 86 144 84 136 80C140 92 148 100 158 104C146 110 130 104 122 92C118 82 116 72 112 66Z', hair);
    // ножки: на цыпочках
    s += K.line('M96 150L98 176', '#7a4a3a', 6.4) + K.line('M96 150L98 176', '#fdeee4', 4) + K.line('M106 148C114 156 122 158 128 154', '#7a4a3a', 6.4) + K.line('M106 148C114 156 122 158 128 154', '#fdeee4', 4);
    s += K.part('M94 174L100 172L102 178L96 179Z', '#a78bfa', { line: '#4c1d95', lw: 1.2 }) + K.part('M126 150L132 154L128 158L124 156Z', '#a78bfa', { line: '#4c1d95', lw: 1.2 });
    // юбка из лепестков в два слоя
    s += K.vol('M90 114C72 126 56 142 50 156C58 158 64 154 68 160C74 154 82 158 86 162C92 156 108 156 114 162C118 158 126 154 132 160C136 154 142 158 150 156C144 142 128 126 110 114Z', { c1: '#a7f3d0', c2: '#0d9488', rim: '#eef0ff', texK: 0.2, lw: 2.2, line: '#134e4a' });
    s += K.vol('M92 114C80 124 72 134 68 144C76 142 82 146 88 144C94 140 106 140 112 144C118 146 124 142 132 144C128 134 120 124 108 114Z', { c1: '#e9d5ff', c2: '#8b5cf6', rim: '#eef0ff', tex: false, lw: 2, line: '#4c1d95' });
    // лиф
    s += K.vol('M100 90C108 90 112 96 112 104L110 116H90L88 104C88 96 92 90 100 90Z', { c1: '#c4b5fd', c2: '#6d28d9', tex: false, lw: 2, line: '#3b0764' });
    // руки: левая над головой, правая в сторону
    s += K.line('M90 96C78 88 72 74 78 58', '#7a4a3a', 6.8) + K.line('M90 96C78 88 72 74 78 58', '#fdeee4', 4.4);
    s += K.line('M110 96C124 98 138 94 150 86', '#7a4a3a', 6.8) + K.line('M110 96C124 98 138 94 150 86', '#fdeee4', 4.4);
    s += K.leaf(150, 86, 18, -40, '#4ade80');
    // голова, ушки, венок
    s += K.mirror(K.part('M86 70L74 60L86 64Z', '#fdeee4', { line: '#7a4a3a', lw: 1.6 }));
    s += K.vol(K.ell(100, 70, 15, 16), skin);
    s += K.part('M85 68C84 56 92 50 100 50C108 50 116 56 115 68C110 60 104 58 98 60C92 60 88 64 85 68Z', '#6ee7b7', { line: '#0f5f45', lw: 1.6 });
    const fl = (x, y, c) => `<g fill="${c}" stroke="${K.shade(c, -0.5)}" stroke-width=".7">${[0, 72, 144, 216, 288].map(a => `<circle cx="${f(x + 2.4 * Math.cos(a * Math.PI / 180))}" cy="${f(y + 2.4 * Math.sin(a * Math.PI / 180))}" r="1.9"/>`).join('')}</g><circle cx="${x}" cy="${y}" r="1.2" fill="#fde68a"/>`;
    s += fl(86, 56, '#f9a8d4') + fl(100, 50, '#fef9c3') + fl(114, 56, '#c4b5fd');
    s += K.closed(100, 72, 6.5, 4.4, true) + K.blush(90, 78, 3.4) + K.blush(110, 78, 3.4) + K.mouth('smile', 100, 79, 7);
    // передний ряд грибов и ветерок
    for (const a of [20, 55, 90, 125, 160]) { const [x, y] = ring(a); s += shroom(x, y, 1); }
    s += K.line('M22 110C30 100 44 102 42 112M176 128C184 120 186 108 176 106', '#ffffff', 2, { op: 0.5, cls: 'art-float' });
    s += K.spark(30, 60, 3.2, '#f5f3ff', 'art-float') + K.spark(172, 40, 2.8, '#a7f3d0') + K.spark(62, 26, 2.4, '#f0abfc', 'art-float') + K.spark(184, 150, 2.4, '#e0e7ff');
    return s;
  },

  // Королева Мэб: королева фей и снов стоит в колеснице из скорлупки лесного ореха с колёсами-паутинками. За спиной —
  // огромные крылья ночной бабочки с лунами, длинные серебристые волосы, корона из росинок с месяцем, в руке — жезл
  // со звездой, от которого плывут пузыри-сны; глаза блаженно зажмурены
  ce_mab(K) {
    const f = K.f;
    const skin = { c1: '#fdf0ea', c2: '#e3b4a4', rim: '#eef0ff', tex: false, lw: 2.2, line: '#6b3a4a' };
    const robe = { c1: '#818cf8', c2: '#1e1b4b', rim: '#eef0ff', rimK: 0.6, texK: 0.3, lw: 2.4, line: '#0f0d33' };
    const hair = { c1: '#f5f3ff', c2: '#a5b4fc', rim: '#ffffff', tex: false, lw: 2, line: '#4338ca' };
    let s = K.aura('#a5b4fc', 100, 96, 0.45) + K.aura('#f0abfc', 60, 80, 0.2);
    // крылья ночной бабочки с лунами
    const wf = K.lin(['#f5f3ff', '#c7d2fe', '#818cf8'], 0, 0, 1, 1);
    const wing = `<g class="art-wing"><path d="M92 96C72 60 40 36 14 40C6 52 16 80 38 96C54 106 76 108 92 106Z" fill="${wf}" fill-opacity=".9" stroke="#3730a3" stroke-width="2" stroke-linejoin="round"/>` +
      `<path d="M92 108C74 112 52 124 42 142C40 152 54 154 68 144C80 136 88 124 94 112Z" fill="${wf}" fill-opacity=".85" stroke="#3730a3" stroke-width="2" stroke-linejoin="round"/>` +
      `<circle cx="44" cy="66" r="10" fill="#fef9c3" stroke="#3730a3" stroke-width="1.4"/><circle cx="48" cy="63" r="8.4" fill="#c7d2fe"/>` +
      K.line('M92 100C70 84 46 64 22 46M92 104C72 96 50 88 30 86M92 112C80 124 66 136 50 146', '#4338ca', 1.1, { op: 0.6 }) +
      K.stitch('M20 46C12 58 20 78 38 92', '#f0abfc', 1.4) + '</g>';
    s += K.mirror(wing);
    // волосы
    s += K.vol('M82 56C66 66 62 90 64 114C66 128 62 138 56 146H80C82 128 84 104 88 80Z', hair);
    s += K.vol('M118 56C134 66 138 90 136 114C134 128 138 138 144 146H120C118 128 116 104 112 80Z', hair);
    // мантия
    s += K.vol('M100 86C116 86 126 98 130 114C134 128 136 140 138 150H62C64 140 66 128 70 114C74 98 84 86 100 86Z', robe);
    s += `<g opacity=".9">${K.spark(86, 118, 2.4, '#fef9c3', '')}${K.spark(114, 128, 2, '#fef9c3', '')}${K.spark(96, 140, 1.8, '#fef9c3', '')}${K.spark(78, 136, 1.6, '#fef9c3', '')}</g>`;
    s += K.stitch('M82 96Q100 106 118 96', '#f0abfc', 1.6) + K.rhomb(100, 102, 3.4, '#f0abfc', '#3b0764');
    // левая рука на борту колесницы
    s += K.vol('M76 102C66 110 60 124 60 138C64 142 70 142 72 138C72 126 76 116 82 110Z', robe) + K.vol(K.ell(64, 142, 5.5, 5), skin);
    // колесница — скорлупка ореха
    s += K.vol('M42 144C42 170 68 180 100 180C132 180 158 170 158 144Z', { c1: '#d6a878', c2: '#6b3a14', rim: '#fde68a', tex: false, lw: 2.4, line: '#3b1d08' });
    s += K.line('M60 150C62 164 70 172 80 176M100 150V179M140 150C138 164 130 172 120 176', '#6b3a14', 1.6, { op: 0.6 });
    s += K.part('M38 140Q100 152 162 140L160 148Q100 160 40 148Z', '#a16207', { line: '#3b1d08', lw: 1.8 }) + K.stitch('M44 145Q100 155 156 145', '#fde68a', 1.2);
    // колёса-паутинки
    const wheel = (x, y) => {
      let w = `<circle cx="${x}" cy="${y}" r="15" fill="#e0e7ff" fill-opacity=".15" stroke="#e2e8f0" stroke-width="2"/>`;
      for (let i = 0; i < 8; i++) { const a = i * 45 * Math.PI / 180; w += K.line(`M${x} ${y}L${f(x + 15 * Math.cos(a))} ${f(y + 15 * Math.sin(a))}`, '#e2e8f0', 1); }
      return w + `<circle cx="${x}" cy="${y}" r="6" fill="none" stroke="#e2e8f0" stroke-width=".9"/><circle cx="${x}" cy="${y}" r="10.5" fill="none" stroke="#e2e8f0" stroke-width=".9"/><circle cx="${x}" cy="${y}" r="2.4" fill="#fde68a"/>`;
    };
    s += wheel(40, 164) + wheel(160, 164);
    // голова и корона из росинок с месяцем
    s += K.vol(K.ell(100, 68, 17, 18), skin);
    s += K.part('M83 66C82 54 90 48 100 48C110 48 118 54 117 66C112 58 106 55 100 57C94 55 88 58 83 66Z', '#eef2ff', { line: '#4338ca', lw: 1.6 });
    s += K.part('M84 52L86 38L92 46L100 30L108 46L114 38L116 52Q100 47 84 52Z', '#e0e7ff', { line: '#4338ca', lw: 1.5 });
    s += `<circle cx="86" cy="37" r="2.2" fill="#a5f3fc"/><circle cx="114" cy="37" r="2.2" fill="#a5f3fc"/>` + `<path d="M96 26A6 6 0 1 0 104 33A4.6 4.6 0 0 1 96 26Z" fill="#fde68a" stroke="#92400e" stroke-width="1"/>`;
    s += K.closed(100, 71, 7.5, 5, true) + K.line('M90 67l-2 -2M110 67l2 -2', K.INK, 1.4);
    s += K.blush(88, 77, 3.4) + K.blush(112, 77, 3.4) + K.mouth('smile', 100, 79, 8);
    // правая рука с жезлом-звездой
    s += K.line('M130 110L150 56', '#4338ca', 4.4) + K.line('M130 110L150 56', '#e0e7ff', 2);
    s += `<circle class="art-aura" cx="151" cy="50" r="16" fill="${K.rad([[0, '#fef9c3', 0.9], [1, '#f0abfc', 0]])}"/>` + K.spark(151, 50, 9, '#fef9c3');
    s += K.vol('M118 98C128 102 134 108 134 116C130 120 124 120 122 116C120 110 116 106 112 104Z', robe) + K.vol(K.ell(131, 112, 5.5, 5), skin);
    // пузыри-сны
    const dream = (x, y, r, d, inner) => `<g class="art-float" style="animation-delay:${d}s"><circle cx="${x}" cy="${y}" r="${r}" fill="${K.rad([[0.6, '#e0e7ff', 0.12], [1, '#f0abfc', 0.5]])}" stroke="#f5f3ff" stroke-width="1.2"/><ellipse cx="${f(x - r * 0.4)}" cy="${f(y - r * 0.45)}" rx="${f(r * 0.25)}" ry="${f(r * 0.14)}" transform="rotate(-35 ${f(x - r * 0.4)} ${f(y - r * 0.45)})" fill="#fff" opacity=".8"/>${inner}</g>`;
    s += dream(172, 26, 10, -0.2, `<path d="M169 21A5.6 5.6 0 1 0 176 29A4.2 4.2 0 0 1 169 21Z" fill="#fde68a"/>`);
    s += dream(182, 72, 8, -1, `<path d="M178 75V70L182 66L186 70V75Z" fill="#c7d2fe" stroke="#4338ca" stroke-width=".8"/><rect x="181" y="71" width="2.2" height="2.2" fill="#fde68a"/>`);
    s += dream(24, 20, 7, -0.6, `<path d="M21 18h5l-5 5h5" fill="none" stroke="#e0e7ff" stroke-width="1.2" stroke-linejoin="round"/>`);
    s += K.spark(160, 96, 2.6, '#fef9c3', 'art-float') + K.spark(14, 110, 2.4, '#e0e7ff') + K.spark(188, 120, 2.4, '#f0abfc');
    return s;
  },

  // Брауни: косматый шотландский домовичок, весь в бурой шерсти, как лохматая швабра; из-под чёлки блестят глазки, нос
  // картошкой, большие босые ступни. Ночью чинит свет: в поднятой руке — горящая лампочка, в другой — отвёртка;
  // рядом стоит миска сливок — единственная награда, которую он принимает
  ce_brownie(K) {
    const fur = { c1: '#d6a878', c2: '#5a3416', rim: '#fff6b0', rimK: 0.55, texK: 0.12, lw: 2.4, line: '#2a1406' };
    const skin = { c1: '#f3c6a0', c2: '#c0845a', rim: '#fff6b0', tex: false, lw: 2, line: '#6a3a1a' };
    let s = K.aura('#facc15', 90, 110, 0.4);
    // миска сливок
    s += K.vol('M138 166C138 176 146 180 160 180C174 180 182 176 182 166Z', { c1: '#c08a54', c2: '#5a3416', tex: false, lw: 2, line: '#2a1406' });
    s += `<ellipse cx="160" cy="166" rx="22" ry="5" fill="${K.lin(['#ffffff', '#fef3c7'])}" stroke="#2a1406" stroke-width="2"/>` + K.line('M150 166Q156 164 162 166', '#ffffff', 1.4) + K.stitch('M142 172Q160 177 178 172', '#fde68a', 1.2);
    // босые ступни
    s += K.mirror(K.vol('M68 172C66 164 76 162 88 164C96 166 98 172 96 178H70C68 176 68 174 68 172Z', skin) + K.line('M76 166V170M82 165V169M88 166V170', '#6a3a1a', 1.2, { op: 0.7 }));
    // левая рука поднята, в ней лампочка
    s += K.vol('M64 110C54 100 50 86 52 72C56 66 64 68 64 74C64 86 68 96 74 104Z', fur);
    s += `<circle class="art-aura" cx="56" cy="44" r="26" fill="${K.rad([[0, '#fffbe6', 0.95], [0.4, '#fde047', 0.55], [1, '#facc15', 0]])}"/>`;
    s += `<path d="M47 56C40 50 42 32 56 30C70 32 72 50 65 56Z" fill="${K.rad([[0, '#ffffff'], [0.6, '#fef9c3'], [1, '#fde047']])}" stroke="#a16207" stroke-width="1.8"/>`;
    s += K.line('M52 55V48L54 44L56 48L58 44L60 48V55', '#f59e0b', 1.4);
    s += K.part('M48 56H64V64H48Z', '#cbd5e1', { line: '#334155', lw: 1.6 }) + K.line('M48 59H64M48 62H64', '#64748b', 1);
    s += K.vol(K.ell(56, 68, 7, 6), skin);
    // тело — лохматая копна
    const body = 'M100 64C130 64 146 86 148 112C150 134 150 150 146 164L140 158L134 168L126 160L118 170L110 161L100 171L90 161L82 170L74 160L66 168L60 158L54 164C50 150 50 134 52 112C54 86 70 64 100 64Z';
    s += K.vol(body, fur);
    s += K.line('M62 120C60 136 62 150 66 162M76 124C74 140 76 154 80 166M124 124C126 140 124 154 120 166M138 120C140 136 138 150 134 162M100 136V166M88 132C86 146 88 158 90 166M112 132C114 146 112 158 110 166', '#5a3416', 1.6, { op: 0.6 });
    s += K.gloss(72, 84, 9, 5, -40, 0.35);
    // глазки из-под чёлки смотрят на лампочку
    s += K.eyes(100, 102, 15, 9.5, { iris: '#7c4a1d', look: [-0.5, -0.4] });
    s += K.part('M62 98C64 76 80 66 100 66C120 66 136 76 138 98L132 92L126 99L119 91L112 98L106 90L100 98L94 90L88 98L81 91L74 99L68 92Z', '#b07a48', { line: '#2a1406', lw: 1.8 });
    s += K.line('M74 80L78 92M88 74L90 88M104 72V86M118 76L114 90M130 82L126 92', '#5a3416', 1.4, { op: 0.6 });
    // нос картошкой и улыбка в бороду
    s += `<ellipse cx="100" cy="118" rx="9.5" ry="8" fill="${K.rad([[0, '#fbbf9a'], [1, '#d97a55']], 0.4, 0.35, 0.7)}" stroke="#6a3a1a" stroke-width="1.8"/><ellipse cx="97" cy="115" rx="3" ry="1.8" fill="#fff" opacity=".7"/>`;
    s += K.blush(80, 120, 5) + K.blush(120, 120, 5) + K.mouth('smile', 100, 130, 12);
    // правая рука с отвёрткой
    s += K.vol('M138 114C148 116 154 124 154 134C150 138 144 138 142 134C142 128 138 124 132 122Z', fur);
    s += K.line('M150 136L168 118', '#94a3b8', 2.6) + K.part('M146 140L154 132L158 136L150 144Z', '#ef4444', { line: '#7f1d1d', lw: 1.4 }) + K.line('M150 138L155 133', '#fde047', 1.4);
    s += K.vol(K.ell(149, 137, 6.5, 6), skin);
    s += K.spark(168, 116, 3.4, '#fde047') + K.spark(28, 70, 2.6, '#fef9c3', 'art-float') + K.spark(90, 28, 2.4, '#fde047', 'art-float') + K.spark(176, 140, 2.2, '#fef9c3');
    return s;
  },

  // Боггарт: обиженный Брауни. Шерсть встала дыбом от статического электричества и потрескивает молниями, уши торчат,
  // глаза сердито горят, ухмылка с зубами. Одной лапой он щёлкает выключателем на стене (пробки вылетают снопом искр),
  // в другой прячет пульт от телевизора — пока не нальют сливок, не отдаст
  ce_boggart(K) {
    const f = K.f;
    const fur = { c1: '#b8aea4', c2: '#3a3430', rim: '#fff6b0', rimK: 0.6, texK: 0.2, lw: 2.4, line: '#1c1917' };
    const skin = { c1: '#d9b08c', c2: '#8a5a3a', rim: '#fff6b0', tex: false, lw: 2, line: '#3a200e' };
    let s = K.aura('#facc15', 96, 104, 0.45);
    // шерсть дыбом
    let spikes = '';
    for (let i = 0; i <= 24; i++) {
      const a = (-180 + i * 7.5) * Math.PI / 180, r = i % 2 ? 50 : 72;
      spikes += `${i ? 'L' : 'M'}${f(100 + r * Math.cos(a) * 1.05)} ${f(106 + r * Math.sin(a))}`;
    }
    s += K.vol(spikes + 'L150 120L50 120Z', { ...fur, texK: 0.1 });
    for (const [x, y] of [[26, 104], [44, 60], [78, 36], [122, 36], [156, 60], [174, 104]]) s += K.line(`M${x} ${y}l4 -6l-3 -1l4 -7`, '#fde047', 2, { cls: 'art-blink' });
    // острые уши
    s += K.mirror(K.vol('M58 104C42 96 30 82 22 68C38 72 54 82 64 94Z', { ...fur, tex: false }) + K.part('M56 98C46 92 38 84 32 76C42 80 52 86 60 94Z', '#d4a58a', { lw: 0 }));
    // ступни
    s += K.mirror(K.vol('M66 172C64 164 76 162 88 164C96 166 98 172 96 178H68C66 176 66 174 66 172Z', skin));
    // тело
    const body = 'M100 70C132 70 150 92 152 118C154 140 154 154 150 166L143 160L136 170L128 162L120 172L110 163L100 173L90 163L80 172L72 162L64 170L57 160L50 166C46 154 46 140 48 118C50 92 68 70 100 70Z';
    s += K.vol(body, fur);
    s += K.line('M62 124C60 140 62 154 66 164M78 128C76 144 78 158 82 168M122 128C124 144 122 158 118 168M138 124C140 140 138 154 134 164', '#1c1917', 1.6, { op: 0.5 });
    s += K.line('M60 130l6 4l-5 3l7 5M140 132l-6 4l5 3l-7 5', '#fde047', 1.8, { cls: 'art-blink' });
    // сердитые глаза, кривой нос, зубастая ухмылка
    s += K.eyes(100, 102, 17, 10.5, { iris: '#facc15', lid: 'angry', skin: '#6b625a', look: [0.6, 0.1] });
    s += `<path d="M96 110C92 116 94 124 100 125C108 126 110 120 106 114C104 111 100 108 96 110Z" fill="${K.rad([[0, '#d9a68a'], [1, '#8a5a3a']], 0.4, 0.35, 0.7)}" stroke="#3a200e" stroke-width="1.8"/>`;
    s += K.mouth('teeth', 100, 132, 26);
    s += K.gloss(72, 90, 8, 4.5, -40, 0.3);
    // левая лапа прячет пульт
    s += K.vol('M52 128C42 134 36 144 36 154C40 160 48 160 50 154C50 146 54 140 60 136Z', fur);
    s += K.part('M24 136L38 132L46 160L32 164Z', '#1f2937', { line: '#000', lw: 1.8 });
    s += `<circle cx="33" cy="140" r="2.2" fill="#ef4444"/><circle cx="36" cy="148" r="1.5" fill="#94a3b8"/><circle cx="40" cy="146" r="1.5" fill="#94a3b8"/><circle cx="38" cy="154" r="1.5" fill="#94a3b8"/><circle cx="42" cy="152" r="1.5" fill="#94a3b8"/>`;
    s += K.vol(K.ell(44, 152, 6.5, 6), skin);
    // выключатель на стене и сноп искр
    s += `<circle class="art-aura" cx="166" cy="90" r="22" fill="${K.rad([[0, '#fef9c3', 0.8], [1, '#facc15', 0]])}"/>`;
    s += K.part('M154 74H178V104H154Z', '#f1f5f9', { line: '#475569', lw: 1.8 }) + K.part('M161 80H171V98H161Z', '#e2e8f0', { line: '#64748b', lw: 1.4 }) + K.part('M162 81H170V89H162Z', '#94a3b8', { flat: true, lw: 0 });
    s += K.line('M180 70l8 -8M184 82l10 -2M178 64l2 -10M150 68l-6 -6', '#fde047', 2.2, { cls: 'art-blink' });
    s += K.spark(190, 58, 4, '#fef9c3') + K.spark(172, 52, 3, '#fde047', 'art-float');
    s += K.vol('M144 116C150 108 154 100 158 94C162 90 168 92 166 98C162 106 156 116 150 124Z', fur) + K.vol(K.ell(163, 93, 6, 5.5), skin);
    s += K.spark(18, 90, 2.6, '#fde047', 'art-float') + K.spark(30, 176, 2.2, '#fef9c3');
    return s;
  },

  // Пука: проказник-оборотень, пока в облике чёрного пушистого зайчонка — но с козлиными рожками, глаза горят
  // золотом. В лапках — веточка ежевики, мордочка перемазана ягодным соком. А его тень за спиной уже примеряет облик коня
  ce_puca(K) {
    const fur = { c1: '#4b5567', c2: '#0b1020', rim: '#e9d5ff', rimK: 0.6, texK: 0.5, lw: 2.6, line: '#050814' };
    let s = K.aura('#a78bfa', 90, 110, 0.4);
    // тень-конь за спиной
    s += `<path d="M118 162C116 132 124 106 138 86C140 72 146 60 156 54L157 40L165 51C175 53 185 61 191 71C195 77 192 83 186 82C180 80 174 80 170 84C164 96 158 112 156 130C154 146 156 158 158 166Z" fill="#7c3aed" opacity=".25"/>` +
      `<path d="M150 58C144 70 138 84 132 100M156 64C150 78 146 92 142 108" stroke="#7c3aed" stroke-width="5" stroke-linecap="round" opacity=".22"/>`;
    s += `<ellipse class="art-blink" cx="170" cy="62" rx="2.6" ry="2" fill="#fbbf24" opacity=".7"/>`;
    // уши: одно торчит, другое свесилось
    s += K.vol('M82 88C70 62 68 32 78 20C90 26 94 56 94 84Z', fur) + K.part('M82 80C76 60 76 40 80 30C86 38 88 58 88 78Z', '#6d4c9f', { lw: 0 });
    s += K.vol('M114 82C128 64 148 56 166 60C162 72 146 84 124 92Z', fur) + K.part('M120 82C132 70 146 64 158 64C152 72 140 80 126 86Z', '#6d4c9f', { lw: 0 });
    // рожки
    s += K.part('M90 82C84 72 86 62 94 58C92 66 94 72 98 78Z', '#d6c7a1', { line: '#44403c', lw: 1.6 }) + K.part('M110 80C114 70 120 64 128 66C122 70 118 76 116 84Z', '#d6c7a1', { line: '#44403c', lw: 1.6 });
    // лапки
    s += K.mirror(K.vol(K.ell(78, 172, 15, 8), { ...fur, tex: false, lw: 2.2 }));
    // хвостик-пушок
    s += K.vol(K.ell(146, 160, 10, 9), { ...fur, tex: false });
    // тело
    s += K.vol('M100 76C136 76 152 102 150 130C148 158 128 176 100 176C72 176 52 158 50 130C48 102 64 76 100 76Z', fur);
    s += K.line('M52 118l-4 4l5 2M148 118l4 4l-5 2M60 158l-4 4l5 1M140 158l4 4l-5 1', '#050814', 2);
    s += `<ellipse cx="100" cy="150" rx="26" ry="20" fill="${K.rad([[0, '#64748b', 0.7], [1, '#64748b', 0]])}"/>`;
    s += K.gloss(74, 96, 9, 5, -40, 0.25);
    // горящие глаза
    s += K.glow(84, 112, 8, 10, '#fbbf24') + K.glow(116, 112, 8, 10, '#fbbf24');
    s += `<ellipse cx="84" cy="113" rx="2" ry="5" fill="#1c1917"/><ellipse cx="116" cy="113" rx="2" ry="5" fill="#1c1917"/>`;
    // носик, ротик в ягодном соке
    s += `<path d="M96 124L104 124L100 129Z" fill="#c084fc" stroke="#050814" stroke-width="1.2" stroke-linejoin="round"/>`;
    s += K.mouth('cat', 100, 130, 12) + `<ellipse cx="108" cy="134" rx="4" ry="2.4" fill="#7e22ce" opacity=".7"/><circle cx="92" cy="135" r="1.4" fill="#7e22ce" opacity=".7"/>`;
    // веточка ежевики в лапках
    s += K.line('M60 170C72 156 90 150 112 146C126 144 140 138 148 130', '#4d7c0f', 2.4) + K.leaf(78, 158, 14, -130, '#4d7c0f') + K.leaf(130, 142, 13, -40, '#65a30d');
    const berry = (x, y) => [[0, 0], [-2.6, -1.4], [2.6, -1.4], [-1.4, 1.6], [1.4, 1.6], [0, -3]].map(([dx, dy]) => `<circle cx="${x + dx}" cy="${y + dy}" r="2.1" fill="${K.rad([[0, '#a78bfa'], [1, '#3b0764']], 0.35, 0.3, 0.8)}" stroke="#1e0533" stroke-width=".6"/>`).join('') + `<circle cx="${x - 1}" cy="${y - 1.6}" r=".7" fill="#fff" opacity=".8"/>`;
    s += berry(92, 152) + berry(112, 150) + berry(146, 132);
    s += K.mirror(K.vol(K.ell(84, 154, 8, 6.5), { ...fur, tex: false, lw: 2 }));
    s += K.spark(30, 50, 3, '#fde68a') + K.spark(24, 120, 2.6, '#e9d5ff', 'art-float') + K.spark(60, 20, 2.2, '#e9d5ff', 'art-float');
    return s;
  },

  // Пука-скакун: любимый облик Пуки — чёрный конь в профиль, одна нога приподнята. Грива и хвост — клубы ночного дыма
  // с золотыми искрами, на голове остались козлиные рожки Пуки, глаза горят золотом; за копытами светятся следы
  ce_pucahorse(K) {
    const f = K.f;
    const hide = { c1: '#4b5567', c2: '#020617', rim: '#e9d5ff', rimK: 0.65, texK: 0.45, lw: 2.6, line: '#010208' };
    let s = K.aura('#8b5cf6', 96, 108, 0.4);
    s += `<path d="M160 30A12 12 0 1 0 172 46A9 9 0 0 1 160 30Z" fill="#fde68a" opacity=".85"/>`;
    // светящиеся следы копыт
    s += [[18, 176], [34, 172], [46, 178]].map(([x, y], i) => `<path class="art-blink" style="animation-delay:-${i * 0.5}s" d="M${x - 4} ${y}A4 3 0 1 1 ${x + 4} ${y}L${x + 2} ${y}A2 1.6 0 1 0 ${x - 2} ${y}Z" fill="#fbbf24" opacity=".8"/>`).join('');
    // хвост из дыма
    const smoke = (x, y, h, w, r, d) => K.g(K.flame(x, y, h, w, '#a78bfa', '#1e1b4b', { style: `animation-delay:${d}s` }), `rotate(${r} ${x} ${y})`);
    s += smoke(150, 112, 50, 26, 70, -0.3) + smoke(152, 118, 40, 20, 100, -0.8) + smoke(150, 110, 34, 18, 45, -1.2);
    // дальние ноги
    const far = { ...hide, c1: '#2a3242', texK: 0.2, lw: 2.2 }, near = { ...hide, texK: 0.25, lw: 2.2 };
    const hoof = d => `<path d="${d}" fill="${K.lin(['#fde68a', '#d97706'])}" stroke="#78350f" stroke-width="1.4" stroke-linejoin="round"/>`;
    s += K.vol('M136 126C144 128 148 132 148 140L149 170L139 170L138 142Z', far) + K.vol('M82 128C90 128 94 132 94 140L95 170L85 170L84 142Z', far);
    s += hoof('M138 169H150L152 178H137Z') + hoof('M84 169H96L98 178H83Z');
    // шея и туловище
    s += K.vol('M72 118C62 102 58 84 62 68C64 58 80 52 90 60C94 76 100 92 110 104Z', hide);
    s += K.vol('M66 114C68 98 86 90 112 90C140 90 158 100 158 118C158 134 142 142 112 142C88 142 64 132 66 114Z', hide);
    s += K.line('M72 106C80 96 92 92 104 92', '#e9d5ff', 1.6, { op: 0.35 });
    // ближние ноги: передняя приподнята
    s += K.vol('M120 126C130 126 136 132 135 142L134 172L123 172L122 144Z', near);
    s += K.vol('M72 122C80 122 88 126 86 134C82 140 76 144 68 148L62 152L57 144L64 140C68 136 70 132 70 128Z', near);
    s += hoof('M122 171H135L137 180H121Z') + hoof('M57 143L50 150L58 157L63 151Z');
    // голова
    s += K.vol('M64 42C78 40 90 48 90 60C90 70 84 76 76 82C68 90 56 98 44 98C34 98 28 92 30 84C32 76 40 70 46 62C50 52 54 44 64 42Z', hide);
    s += `<ellipse cx="40" cy="88" rx="12" ry="9" fill="${K.rad([[0, '#64748b', 0.8], [1, '#64748b', 0]])}"/>`;
    s += `<ellipse cx="36" cy="88" rx="2.6" ry="1.8" fill="#010208"/>` + K.line('M34 95Q40 97 46 94', '#010208', 1.8);
    // уши и рожки
    s += K.part('M70 44L72 26L80 42Z', '#1e2533', { line: '#010208', lw: 1.8 }) + K.part('M78 46C84 36 94 32 102 34C96 38 90 44 86 50Z', '#d6c7a1', { line: '#44403c', lw: 1.6 });
    // горящий глаз
    s += K.glow(66, 60, 5.5, 6.5, '#fbbf24') + `<ellipse cx="66" cy="61" rx="1.4" ry="3.6" fill="#1c1917"/>`;
    s += K.line('M58 54Q66 50 74 54', '#010208', 2.2);
    // грива из дыма
    s += smoke(76, 44, 30, 20, 50, -0.2) + smoke(86, 62, 30, 20, 60, -0.9) + smoke(96, 80, 28, 18, 66, -0.5) + smoke(106, 94, 24, 16, 72, -1.3);
    s += K.gloss(96, 100, 10, 4.5, -10, 0.25);
    s += K.spark(118, 60, 3, '#fbbf24', 'art-float') + K.spark(178, 90, 2.6, '#fde68a') + K.spark(20, 40, 2.6, '#e9d5ff', 'art-float') + K.spark(40, 130, 2.2, '#e9d5ff');
    return s;
  },
  // Уэльский дракон: пухлый красный дракон с флага Уэльса сидит на зелёном холме (по гребню холма — белая полоса флага).
  // Перепончатые крылья подняты, золотые рожки и гребень, брюшко в золотых пластинах, хвост со стрелкой. В лапе держит
  // нарцисс — цветок Уэльса, а сам зажмурился и чихает искрами
  ce_draig(K) {
    const R = { c1: '#f87171', c2: '#991b1b', rim: '#ffe29a', rimK: 0.65, texK: 0.25, lw: 2.6, line: '#450a0a' };
    let s = K.aura('#ff7a3d', 96, 106, 0.45);
    // холм цвета флага
    s += `<path d="M12 180C18 160 50 150 100 150C150 150 182 160 188 180Z" fill="${K.lin(['#4ade80', '#15803d'])}" stroke="#14532d" stroke-width="2"/>`;
    s += K.line('M22 164C44 154 70 150 100 150C130 150 156 154 178 164', '#f8fafc', 4, { op: 0.85 });
    s += K.line('M30 172q3-6 6-8M150 170q3-6 7-7M164 176q2-5 6-6', '#bbf7d0', 1.6, { op: 0.8 });
    // крылья
    const wing = `<g class="art-wing"><path d="M80 110C66 84 44 64 14 56C22 68 22 80 18 92C28 88 38 92 40 102C46 94 56 94 60 102C64 108 70 114 76 118Z" fill="${K.lin(['#fca5a5', '#dc2626', '#7f1d1d'], 0, 0, 0.4, 1)}" stroke="#450a0a" stroke-width="2" stroke-linejoin="round"/>` +
      K.line('M80 110C62 86 40 68 16 58M78 114C60 100 38 94 20 92M76 118C64 108 52 102 40 102', '#7f1d1d', 2.6) + `<path d="M14 56l-5 -6l9 2z" fill="#fde68a" stroke="#450a0a" stroke-width="1"/></g>`;
    s += K.mirror(wing);
    // хвост со стрелкой
    const tail = 'M134 170C160 176 180 164 182 144C184 130 176 120 168 114';
    s += K.line(tail, '#450a0a', 13) + K.line(tail, '#dc2626', 8.5) + K.line(tail, '#fca5a5', 2, { op: 0.5 });
    s += K.part('M164 96C170 102 177 108 177 117C171 115 167 117 169 123C164 119 160 119 155 123C155 114 159 106 164 96Z', '#facc15', { line: '#713f12', lw: 1.8 });
    // задние лапы
    s += K.mirror(K.vol('M54 177C50 164 58 154 70 156C80 158 86 168 84 178Z', R) + `<path d="M56 178l-3 3l6 -1zM64 179l-1 4l4 -3zM72 179l1 4l3 -4z" fill="#fff8e6" stroke="#450a0a" stroke-width="1"/>`);
    // тело и брюшко в пластинах
    s += K.vol('M100 92C128 92 146 114 148 140C150 164 132 178 100 178C68 178 50 164 52 140C54 114 72 92 100 92Z', R);
    s += `<path d="M100 106C116 106 126 124 126 146C126 164 116 174 100 174C84 174 74 164 74 146C74 124 84 106 100 106Z" fill="${K.lin(['#fef3c7', '#fcd34d', '#f59e0b'])}" stroke="#92400e" stroke-width="1.8"/>`;
    s += K.line('M80 122Q100 128 120 122M76 136Q100 143 124 136M75 150Q100 157 125 150M78 164Q100 170 122 164', '#b45309', 1.6, { op: 0.8 });
    s += K.gloss(70, 112, 8, 4.5, -40, 0.3);
    // левая лапка на боку
    s += K.vol('M60 122C52 130 50 142 56 150C62 152 68 148 68 142C66 134 64 128 60 122Z', R);
    // правая лапа с нарциссом
    s += K.line('M160 98C162 88 164 80 164 70', '#15803d', 2.6) + K.leaf(162, 90, 16, -60, '#22c55e');
    let petals = '';
    for (let i = 0; i < 6; i++) petals += `<ellipse cx="164" cy="56" rx="5" ry="9" transform="rotate(${i * 60} 164 64)" fill="${K.lin(['#fef9c3', '#fde047'])}" stroke="#a16207" stroke-width="1"/>`;
    s += petals + `<ellipse cx="164" cy="64" rx="6" ry="5" fill="${K.lin(['#fdba74', '#f97316'])}" stroke="#9a3412" stroke-width="1.2"/><ellipse cx="164" cy="63" rx="3.6" ry="2.4" fill="#c2410c"/>`;
    s += K.vol('M138 122C148 116 154 108 156 98C160 94 166 96 164 102C162 114 154 126 144 134Z', R) + K.vol(K.ell(160, 99, 6, 5.5), R);
    // голова: рожки, гребень, уши-оборки
    s += K.mirror(K.part('M78 48C70 36 68 24 72 12C78 20 84 32 90 42Z', '#fde68a', { line: '#713f12', lw: 1.8 }) + K.part('M66 62C54 58 44 50 40 38C52 40 64 46 72 54Z', '#dc2626', { line: '#450a0a', lw: 1.8 }));
    s += K.part('M90 36L94 24L99 33L103 21L108 33L112 26L114 38Z', '#facc15', { line: '#713f12', lw: 1.6 });
    s += K.vol('M100 32C124 32 138 46 138 62C138 78 126 90 110 92H90C74 90 62 78 62 62C62 46 76 32 100 32Z', R);
    s += K.gloss(80, 44, 7, 3.6, -30, 0.4);
    s += `<ellipse cx="100" cy="76" rx="22" ry="13" fill="${K.lin(['#fecaca', '#f87171'])}" stroke="#7f1d1d" stroke-width="1.8"/>`;
    s += `<ellipse cx="92" cy="72" rx="2.6" ry="2" fill="#450a0a"/><ellipse cx="108" cy="72" rx="2.6" ry="2" fill="#450a0a"/>` + K.line('M90 65Q95 62 100 65Q105 62 110 65', '#7f1d1d', 1.6);
    // зажмурился, чихает
    s += K.line('M78 50L90 55L78 60M122 50L110 55L122 60', K.INK, 3.2);
    s += K.mouth('fang', 100, 82, 16) + K.blush(72, 70, 5) + K.blush(128, 70, 5);
    // искры из ноздрей
    s += `<g class="art-float">${K.spark(70, 84, 5, '#fde68a', '')}${K.spark(58, 74, 3.6, '#fff3b0', '')}${K.spark(62, 92, 3, '#ffb347', '')}${K.spark(130, 84, 5, '#fde68a', '')}${K.spark(142, 74, 3.6, '#fff3b0', '')}${K.spark(138, 94, 3, '#ffb347', '')}</g>`;
    s += `<circle cx="50" cy="80" r="4" fill="#e7e5e4" opacity=".55"/><circle cx="44" cy="72" r="2.8" fill="#e7e5e4" opacity=".4"/><circle cx="150" cy="80" r="4" fill="#e7e5e4" opacity=".55"/>`;
    s += K.spark(24, 30, 3, '#fde68a', 'art-float') + K.spark(186, 44, 2.6, '#fff3b0') + K.spark(20, 130, 2.4, '#ffb347');
    return s;
  },

  // Банши: дева из холмов. Серебристые волосы до земли развеваются туманными прядями, лицо бледное, глаза светятся
  // голубым, брови печально подняты — она поёт-плачет, и звук расходится волнами. На плечах серая накидка с брошью-узлом,
  // в руке серебряный гребень; подол тает в тумане
  ce_banshee(K) {
    const hairO = { c1: '#ffffff', c2: '#94a3b8', rim: '#a5f3fc', rimK: 0.6, tex: false, lw: 2.2, line: '#475569' };
    const pale = { c1: '#f8fafc', c2: '#b6c4d4', rim: '#a5f3fc', rimK: 0.6, tex: false, lw: 2.2, line: '#475569' };
    let s = K.aura('#a5f3fc', 96, 100, 0.35);
    // волосы на ветру
    s += K.vol('M84 44C60 50 48 80 52 110C54 130 46 150 30 162C52 166 66 154 72 138C76 120 78 100 84 84Z', hairO);
    s += K.vol('M114 42C142 40 166 56 182 76C172 80 162 78 152 74C162 88 172 96 188 100C172 108 152 104 140 94C144 108 152 118 166 124C150 128 134 120 126 108Z', hairO);
    s += K.line('M70 70C60 96 60 130 44 154M126 50C146 56 162 68 176 78M132 70C146 86 162 96 180 100M130 92C138 104 146 112 158 120', '#e2e8f0', 1.4, { op: 0.8 });
    // платье тает в тумане
    const robe = 'M100 86C118 86 128 98 132 116C138 138 146 156 150 170Q140 164 132 174Q122 164 112 176Q100 166 90 176Q80 164 70 174Q62 164 50 170C54 156 62 138 68 116C72 98 82 86 100 86Z';
    s += K.vol(robe, { c1: '#e2e8f0', c2: '#475569', rim: '#a5f3fc', rimK: 0.6, texK: 0.25, lw: 2.4, line: '#1e293b' });
    s += ceClip(K, robe, `<rect x="40" y="126" width="120" height="54" fill="${ceLinA(K, [[0, '#e0f2fe', 0], [1, '#e0f2fe', 0.9]], 126, 176)}"/>`);
    s += K.line('M88 112C84 130 80 150 76 164M112 112C116 130 120 150 124 164', '#1e293b', 1.6, { op: 0.3 });
    // серая накидка с брошью
    s += K.vol('M72 92C84 86 116 86 128 92L134 116C122 108 78 108 66 116Z', { c1: '#94a3b8', c2: '#334155', rim: '#a5f3fc', tex: false, lw: 2, line: '#0f172a' });
    s += `<circle cx="100" cy="102" r="6.4" fill="${K.lin(['#f1f5f9', '#94a3b8'])}" stroke="#334155" stroke-width="1.4"/>` + ceTriquetra(K, 100, 102.5, 4.4, '#334155', 1.1);
    // левая рука прижата к груди
    s += K.vol('M74 104C66 112 66 124 74 130C80 132 88 128 92 122L86 116C82 120 80 118 80 114Z', pale);
    // правая рука с гребнем
    s += K.vol('M124 100C136 96 144 86 146 76C150 72 156 74 155 80C152 94 142 106 128 112Z', pale);
    s += K.part('M138 60L160 52L163 59L141 67Z', '#e2e8f0', { line: '#475569', lw: 1.6 }) + K.line('M140 60L137 52M144 58L141 50M148 57L145 49M152 55L149 47M156 54L153 46', '#cbd5e1', 1.6) + K.spark(162, 48, 3.4, '#ffffff');
    s += K.vol(K.ell(151, 76, 5.5, 6), pale);
    // лицо
    s += K.vol(K.ell(100, 64, 17, 19), pale);
    s += K.part('M83 62C82 48 90 42 100 42C110 42 118 48 117 62C112 54 106 50 100 52C94 50 88 54 83 62Z', '#f8fafc', { line: '#64748b', lw: 1.6 });
    s += K.glow(92, 65, 4.4, 5.6, '#67e8f9') + K.glow(108, 65, 4.4, 5.6, '#67e8f9');
    s += K.line('M85 58L96 54M104 54L115 58', '#64748b', 1.8);
    s += `<path class="art-blink" d="M89 72q2.4 4 0 6.6q-2.4 -2.6 0 -6.6z" fill="#a5f3fc"/>` + `<ellipse cx="100" cy="77" rx="3.4" ry="4.4" fill="#1e293b"/>`;
    // волны плача
    for (let i = 0; i < 3; i++) s += K.line(`M${60 - i * 9} ${56 - i * 5}Q${50 - i * 11} 67 ${60 - i * 9} ${78 + i * 5}`, '#a5f3fc', 2, { op: 0.65 - i * 0.18, cls: 'art-blink' });
    // туман
    s += [[40, 172, 26], [160, 172, 26], [100, 182, 34]].map(([x, y, r], i) => `<ellipse class="art-float" style="animation-delay:-${i * 0.6}s" cx="${x}" cy="${y}" rx="${r * 1.5}" ry="${r * 0.4}" fill="${K.rad([[0, '#e0f2fe', 0.6], [1, '#a5f3fc', 0]])}"/>`).join('');
    s += K.spark(26, 40, 3, '#e0f2fe', 'art-float') + K.spark(180, 140, 2.6, '#a5f3fc') + K.spark(24, 110, 2.2, '#e0f2fe');
    return s;
  },

  // Кайт Ши: огромный чёрный кот фей с белой звездой на груди сидит у блюдца молока. Уши с кисточками, глаза горят
  // зелёным, серебряные усы, хвост поднят вопросом; над ним — молодой месяц
  ce_caitsith(K) {
    const fur = { c1: '#4b5563', c2: '#030712', rim: '#bbf7d0', rimK: 0.55, texK: 0.45, lw: 2.6, line: '#000000' };
    let s = K.aura('#86efac', 90, 104, 0.3) + K.aura('#a78bfa', 70, 90, 0.25);
    s += `<path d="M160 18A13 13 0 1 0 173 36A10 10 0 0 1 160 18Z" fill="#fde68a" opacity=".9"/>`;
    // хвост вопросом
    const tail = 'M136 170C166 172 182 150 174 126C168 108 172 92 184 86C192 82 196 92 190 96';
    s += K.line(tail, '#000', 16) + K.line(tail, '#1f2937', 11) + K.line(tail, '#6b7280', 2.4, { op: 0.35 });
    // блюдце молока
    s += `<ellipse cx="36" cy="174" rx="24" ry="6.4" fill="${K.lin(['#e0f2fe', '#94a3b8'])}" stroke="#334155" stroke-width="1.8"/><ellipse cx="36" cy="172" rx="15" ry="3.6" fill="#ffffff"/><ellipse cx="30" cy="171" rx="4" ry="1.2" fill="#fff" opacity=".9"/>`;
    // тело
    s += K.vol('M100 88C132 88 150 116 152 144C154 168 138 178 100 178C62 178 46 168 48 144C50 116 68 88 100 88Z', fur);
    s += K.part('M100 110L104.5 120.5L116 122L107.5 129.5L110 141L100 135L90 141L92.5 129.5L84 122L95.5 120.5Z', '#f8fafc', { line: '#94a3b8', lw: 1.4 });
    // передние лапы
    s += K.mirror(K.vol('M72 128C70 146 68 162 68 172C68 178 74 180 82 180C88 180 92 176 92 170C92 158 90 142 88 130Z', fur) + K.line('M74 176V180M80 175V180M86 176V180', '#6b7280', 1.2));
    s += K.gloss(66, 112, 8, 4.5, -40, 0.25);
    // уши с кисточками
    s += K.mirror(K.vol('M64 72L58 24L94 52Z', fur) + K.part('M66 64L63 34L86 52Z', '#6d4c7d', { lw: 0 }) + K.line('M58 24l-3 -9M58 24l2 -9M58 24l6 -6', '#1f2937', 2));
    // голова со щёчками
    s += K.vol('M100 40C130 40 146 58 146 78C146 90 150 96 152 100C144 100 140 104 126 108C118 110 108 112 100 112C92 112 82 110 74 108C60 104 56 100 48 100C50 96 54 90 54 78C54 58 70 40 100 40Z', fur);
    s += K.gloss(78, 54, 7, 3.6, -30, 0.3);
    // глаза горят зелёным, зрачки-щёлки
    s += K.glow(82, 76, 9, 10, '#86efac') + K.glow(118, 76, 9, 10, '#86efac');
    s += `<ellipse cx="82" cy="77" rx="2.2" ry="7" fill="#030712"/><ellipse cx="118" cy="77" rx="2.2" ry="7" fill="#030712"/>`;
    s += `<path d="M95 88H105L100 94Z" fill="#9f7a8a" stroke="#000" stroke-width="1.2" stroke-linejoin="round"/>` + K.line('M100 94V97M92 97Q96 101 100 97Q104 101 108 97', '#9ca3af', 1.8);
    s += K.line('M84 92L54 86M84 96L56 100M116 92L146 86M116 96L144 100', '#e5e7eb', 1.3);
    s += K.spark(24, 60, 3, '#bbf7d0', 'art-float') + K.spark(180, 120, 2.6, '#e9d5ff') + K.spark(140, 20, 2.4, '#fde68a', 'art-float') + K.spark(20, 130, 2.2, '#bbf7d0');
    return s;
  },

  // Морриган: великая королева-прорицательница. Плащ из вороньих перьев раскрыт, как крылья; чёрные волосы, бледное лицо,
  // серебряный венец с тремя зубцами и алым камнем, алые глаза смотрят свысока. В руке копьё, на плече сидит ворон,
  // ещё двое кружат над ней
  ce_morrigan(K) {
    const skin = { c1: '#f7eaee', c2: '#cfa9b8', rim: '#fecaca', tex: false, lw: 2.2, line: '#4a1d2e' };
    const cloakO = { c1: '#4b5563', c2: '#0b0a14', rim: '#fca5a5', rimK: 0.5, texK: 0.5, lw: 2.4, line: '#000000' };
    const hairO = { c1: '#374151', c2: '#050508', rim: '#c4b5fd', rimK: 0.5, tex: false, lw: 2, line: '#000000' };
    let s = K.aura('#dc2626', 96, 100, 0.3) + K.aura('#7c3aed', 70, 90, 0.3);
    s += ceRaven(K, 30, 34, 0.8, false, '-0.3s') + ceRaven(K, 170, 26, 0.65, true, '-1.1s');
    // плащ-крылья из перьев
    const wing = `<g class="art-wing">` + K.vol('M86 90C66 80 42 82 18 98C22 102 26 104 30 104C26 112 26 120 28 126C34 122 38 120 42 120C40 128 40 136 44 144C48 138 52 134 58 132C58 142 60 150 66 158C70 148 74 140 82 132Z', cloakO) +
      K.line('M82 96C62 94 44 98 30 104M82 106C66 108 52 114 42 120M84 116C72 122 64 128 58 132', '#6b7280', 1.2, { op: 0.6 }) + '</g>';
    s += K.mirror(wing);
    // волосы
    s += K.mirror(K.vol('M84 54C70 64 66 88 68 110C70 124 66 134 60 142H84C84 124 84 100 88 78Z', hairO));
    // платье
    s += K.vol('M100 84C118 84 128 96 132 114C138 140 144 160 148 176C124 182 76 182 52 176C56 160 62 140 68 114C72 96 82 84 100 84Z', { c1: '#475569', c2: '#0b0a14', rim: '#fca5a5', rimK: 0.5, texK: 0.4, lw: 2.4, line: '#000000' });
    s += K.part('M70 118Q100 128 130 118L131 127Q100 137 69 127Z', '#b91c1c', { line: '#450a0a', lw: 1.6 });
    s += K.line('M100 128V176', '#b91c1c', 5) + ceTriquetra(K, 100, 152, 8, '#fca5a5', 1.4) + K.stitch('M54 172Q100 180 146 172', '#dc2626', 1.8);
    // воротник из перьев
    s += K.part('M70 92C78 86 122 86 130 92C132 100 128 106 122 104C118 110 112 108 110 104C106 110 94 110 90 104C88 108 82 110 78 104C72 106 68 100 70 92Z', '#1f2937', { line: '#000', lw: 1.6 });
    // левая рука с копьём
    s += K.line('M42 178L56 30', '#1c1917', 5.4) + K.line('M42 178L56 30', '#78716c', 2.4);
    s += K.part('M57 12L63 30L56 40L49 29Z', '#e5e7eb', { line: '#334155', lw: 1.6 }) + K.line('M56 38C50 44 46 52 50 60M56 38C60 46 62 52 58 58', '#dc2626', 2);
    s += K.vol('M76 100C66 104 58 112 54 122C56 128 62 128 66 124C68 116 74 110 82 106Z', cloakO) + K.vol(K.ell(55, 122, 6, 5.5), skin);
    // ворон на плече
    s += `<g class="art-sway" style="transform-origin:50% 100%">` + K.vol('M120 90C120 80 128 74 136 76C144 78 146 86 142 92C140 96 132 98 124 96Z', { ...cloakO, texK: 0.3, lw: 2 }) +
      K.part('M122 94L112 104L120 102Z', '#111827', { line: '#000', lw: 1.4 }) + K.vol(K.ell(140, 72, 7, 6.5), { ...cloakO, tex: false, lw: 2 }) +
      K.part('M146 70L156 73L146 76Z', '#6b7280', { line: '#000', lw: 1.2 }) + `<circle cx="142" cy="70" r="1.8" fill="#f87171"/></g>`;
    // голова
    s += K.vol(K.ell(100, 64, 16, 18), skin);
    s += K.part('M84 64C82 50 90 44 100 44C110 44 118 50 116 64C112 56 106 52 100 54C94 52 88 56 84 64Z', '#1f2937', { line: '#000', lw: 1.6 });
    s += K.part('M84 48L86 34L92 43L100 26L108 43L114 34L116 48Q100 43 84 48Z', '#e5e7eb', { line: '#334155', lw: 1.5 }) + K.rhomb(100, 40, 3.4, '#dc2626', '#450a0a');
    s += K.eyes(100, 66, 7.4, 5.8, { iris: '#dc2626', lid: 'half', skin: '#e8cdd6', lash: true, look: [0.3, 0.1] });
    s += K.line('M95 76Q100 79 105 76', '#9f1239', 2.2);
    s += K.spark(186, 80, 2.6, '#fca5a5') + K.spark(20, 80, 2.4, '#c4b5fd', 'art-float') + K.spark(170, 150, 2.2, '#fca5a5');
    return s;
  },

  // Мананнан мак Лир: бог моря и хозяин острова Мэн. Борода из морской пены, венец из гребней волн с раковиной, за плечами
  // клубится плащ тумана, на груди — трискелион острова Мэн (три бегущие ноги). В руке серебряная ветвь с тремя золотыми
  // яблоками; рядом из волн поднимается голова его коня Энбарра, сотканного из пены
  ce_manannan(K) {
    const f = K.f;
    const skin = { c1: '#f6dccb', c2: '#d6a58c', rim: '#e0f7ff', tex: false, lw: 2.2, line: '#6a3a2a' };
    const foam = { c1: '#ffffff', c2: '#a5c8e0', rim: '#c8f3ff', rimK: 0.6, tex: false, lw: 2.2, line: '#1e4a6e' };
    const robe = { c1: '#38bdf8', c2: '#0c4a6e', rim: '#e0f7ff', rimK: 0.6, texK: 0.25, lw: 2.4, line: '#082f49' };
    let s = K.aura('#38bdf8', 98, 100, 0.4);
    // плащ тумана с завитками
    s += `<path class="art-float" d="M100 50C136 50 162 70 170 100C176 124 178 148 186 168C170 174 30 174 14 168C22 148 24 124 30 100C38 70 64 50 100 50Z" fill="${K.lin(['#e0f2fe', '#7dd3fc', '#0c4a6e'])}" opacity=".45" stroke="#bae6fd" stroke-width="1.6"/>`;
    s += K.line('M40 110c-6-6 0-14 6-10c4 3 0 8-3 6M160 96c6-6 14 0 10 6c-3 4-8 0-6-3M168 140c6-4 12 2 8 7M30 146c-6-2-6-10 0-10', '#e0f2fe', 1.8, { op: 0.6, cls: 'art-float' });
    // белые волосы
    s += K.mirror(K.vol('M84 52C72 60 68 80 70 100C72 112 68 120 62 128H82C82 110 82 90 86 72Z', foam));
    // одеяние
    s += K.vol('M100 82C120 82 132 96 136 116C140 138 144 156 146 170C124 176 76 176 54 170C56 156 60 138 64 116C68 96 80 82 100 82Z', robe);
    s += K.line('M58 160Q66 154 74 160T90 160T106 160T122 160T138 160', '#e0f7ff', 2, { op: 0.8 });
    s += K.line('M84 118C80 136 76 152 74 166M116 118C120 136 124 152 126 166', '#082f49', 1.6, { op: 0.4 });
    s += K.line('M66 132Q100 142 134 132', '#e2e8f0', 4) + K.stitch('M66 132Q100 142 134 132', '#94a3b8', 1.4);
    // трискелион острова Мэн
    s += `<circle cx="100" cy="146" r="10" fill="${K.lin(['#fef08a', '#ca8a04'])}" stroke="#713f12" stroke-width="1.6"/>` + ceThreeLegs(K, 100, 146, 7, '#991b1b');
    // левая рука — ветвь с золотыми яблоками
    s += K.vol('M126 98C138 102 146 112 148 124C144 130 138 130 136 126C134 118 130 112 122 108Z', robe);
    s += K.line('M144 128C150 110 156 92 158 70M154 96C162 92 168 94 172 100M157 80C150 74 146 70 146 62', '#cbd5e1', 2.6) + K.line('M144 128C150 110 156 92 158 70', '#ffffff', 1, { op: 0.8 });
    s += K.leaf(158, 70, 12, -70, '#cbd5e1') + K.leaf(172, 100, 10, 20, '#e2e8f0') + K.leaf(146, 62, 10, -120, '#cbd5e1');
    const apple = (x, y) => `<circle class="art-aura" cx="${x}" cy="${y}" r="9" fill="${K.rad([[0, '#fef9c3', 0.8], [1, '#facc15', 0]])}"/><circle cx="${x}" cy="${y}" r="5.4" fill="${K.rad([[0, '#fef08a'], [0.6, '#facc15'], [1, '#b45309']], 0.35, 0.3, 0.8)}" stroke="#713f12" stroke-width="1.2"/><circle cx="${x - 1.8}" cy="${y - 1.8}" r="1.4" fill="#fff" opacity=".8"/>`;
    s += apple(160, 60) + apple(174, 106) + apple(142, 56);
    s += K.vol(K.ell(145, 126, 6, 5.5), skin);
    // правая рука простёрта над волнами
    s += K.vol('M74 98C62 104 54 114 50 126C52 132 58 132 62 128C64 120 70 114 78 108Z', robe) + K.vol(K.ell(53, 128, 6, 5.5), skin);
    // голова, борода из пены
    s += K.vol(K.ell(100, 62, 17, 18), skin);
    s += K.vol('M80 62C76 84 80 104 90 116C94 122 98 124 100 128C102 124 106 122 110 116C120 104 124 84 120 62C114 74 108 78 100 78C92 78 86 74 80 62Z', foam);
    s += K.line('M88 92c-4 4 0 10 4 6M112 92c4 4 0 10-4 6M98 104c-3 5 2 9 5 5M86 78c-3 4 0 8 3 5M114 78c3 4 0 8-3 5', '#7dabc8', 1.4);
    s += K.mirror(K.part('M100 74C94 70 86 72 82 78C86 80 92 80 100 78Z', '#ffffff', { line: '#1e4a6e', lw: 1.4 }));
    s += `<ellipse cx="100" cy="70" rx="4" ry="3.4" fill="#e8a88c" stroke="#6a3a2a" stroke-width="1.2"/>`;
    s += K.eyes(100, 60, 7.4, 5.4, { iris: '#0e7490', lid: 'half', skin: '#ecc6b0', look: [0.1, 0.2] });
    s += K.mirror(K.part('M86 52C90 48 96 48 99 52C95 51 90 52 86 55Z', '#ffffff', { line: '#1e4a6e', lw: 1.2 }));
    s += K.part('M84 48C80 42 82 36 88 38C88 32 94 30 96 34C96 28 104 28 104 34C106 30 112 32 112 38C118 36 120 42 116 48Q100 42 84 48Z', '#bae6fd', { line: '#0c4a6e', lw: 1.6 });
    s += K.part('M82 50Q100 42 118 50L118 54Q100 47 82 54Z', '#facc15', { line: '#713f12', lw: 1.4 });
    s += `<g transform="translate(100 44)"><path d="M-6 3C-7 -4 -3 -8 0 -8C3 -8 7 -4 6 3Z" fill="${K.lin(['#fff7ed', '#fda4af'])}" stroke="#9f1239" stroke-width="1"/><path d="M-3 2L-2 -6M0 2V-7M3 2L2 -6" stroke="#be123c" stroke-width=".8"/></g>`;
    // волны и конь Энбарр из пены
    s += K.vol('M18 170C16 150 20 132 28 120C26 110 28 100 34 94L32 84L40 92C48 92 56 96 60 104C64 110 62 116 56 116C52 114 48 114 44 118C40 128 38 142 40 156Z', { ...foam, texK: 0.2, tex: true });
    s += `<circle cx="42" cy="100" r="1.8" fill="#0c4a6e"/><ellipse cx="57" cy="108" rx="1.4" ry="1" fill="#0c4a6e"/>`;
    s += K.line('M30 96c-6 4-6 10-2 12c-6 4-6 12 0 14c-6 6-4 14 2 16', '#e0f7ff', 3, { cls: 'art-flicker' });
    const wv = 'M8 170Q18 162 28 170T48 170T68 170T88 170T108 170T128 170T148 170T168 170T188 170';
    s += `<path d="${wv}C188 178 150 186 98 186C46 186 8 178 8 170Z" fill="${ceLinA(K, [[0, '#7dd3fc', 0.85], [1, '#0369a1', 0.95]], 162, 186)}"/>` + K.line(wv, '#f0fdff', 2.4);
    s += K.line('M20 176c4-3 8 0 6 3M150 176c4-3 8 0 6 3M100 178c4-3 8 0 6 3', '#f0fdff', 1.4, { op: 0.7 });
    s += K.spark(184, 40, 3, '#e0f7ff', 'art-float') + K.spark(18, 60, 2.6, '#c8f3ff') + K.spark(130, 22, 2.4, '#fef9c3', 'art-float');
    return s;
  },

  // Дагда (легенда): добрый великан, отец ирландских богов. Огромная рыжая борода, венок из дубовых листьев с желудями,
  // зелёное одеяние с вышивкой и широким поясом. Одной рукой прижимает волшебную арфу, другой мешает черпаком в бездонном
  // котле изобилия, где булькает золотая каша; за спиной сияет трискель
  ce_dagda(K) {
    const skin = { c1: '#fcd9bd', c2: '#d9926a', rim: '#fff3d6', tex: false, lw: 2.2, line: '#7a3a1a' };
    const robe = { c1: '#84cc16', c2: '#1a2e05', rim: '#fde68a', rimK: 0.55, texK: 0.2, lw: 2.6, line: '#0f1a03' };
    const beard = { c1: '#fb923c', c2: '#9a3412', rim: '#fde68a', rimK: 0.5, tex: false, lw: 2.2, line: '#5a1a06' };
    const iron = { c1: '#6b7280', c2: '#0b0f19', rim: '#fde68a', rimK: 0.55, tex: false, lw: 2.4, line: '#000000' };
    let s = K.aura('#a3e635', 100, 100, 0.45) + K.aura('#fde68a', 72, 70, 0.35);
    // сияющий трискель за спиной
    s += `<g class="art-spin-soft"><circle cx="100" cy="64" r="58" fill="none" stroke="#fde68a" stroke-width="2" opacity=".5"/><g opacity=".25">${ceTriskele(K, 100, 64, 54, '#fde68a', 8)}</g>${ceTriskele(K, 100, 64, 54, '#fef3c7', 3)}</g>`;
    // одеяние
    s += K.vol('M100 76C130 76 150 94 158 120C166 146 168 164 166 176C140 184 60 184 34 176C32 164 34 146 42 120C50 94 70 76 100 76Z', robe);
    s += K.line('M70 110C64 132 60 156 58 176M130 110C136 132 140 156 142 176', '#0f1a03', 1.8, { op: 0.4 });
    s += K.stitch('M38 170Q100 184 162 170', '#fde68a', 2) + K.stitch('M40 164Q100 178 160 164', '#fbbf24', 1.2);
    // широкий пояс с пряжкой-трискелем
    s += K.part('M44 128Q100 142 156 128L158 140Q100 154 42 140Z', '#78350f', { line: '#2a1206', lw: 1.8 }) + K.stitch('M46 134Q100 147 154 134', '#fbbf24', 1.4);
    s += `<circle cx="100" cy="141" r="9" fill="${K.lin(['#fef08a', '#ca8a04'])}" stroke="#713f12" stroke-width="1.6"/>` + ceTriskele(K, 100, 141, 6.4, '#713f12', 1.1);
    // арфа
    s += K.line('M130 84C124 118 134 148 154 166', '#713f12', 8) + K.line('M130 84C124 118 134 148 154 166', '#facc15', 4.6);
    s += K.line('M131 86L140 144M136 84L144 138M142 82L148 130M148 82L152 122M154 84L156 114', '#fef9c3', 1.1, { op: 0.9 });
    s += K.vol('M150 164L160 86C163 80 170 82 170 88L162 166Z', { c1: '#d97706', c2: '#78350f', rim: '#fde68a', tex: false, lw: 2, line: '#2a1206' });
    s += K.line('M128 88C142 72 156 74 166 86', '#713f12', 8) + K.line('M128 88C142 72 156 74 166 86', '#facc15', 4.6) + `<circle cx="128" cy="88" r="4" fill="#facc15" stroke="#713f12" stroke-width="1.4"/>`;
    s += ceNote(180, 60, 0.8, '#fde68a', '-0.5s') + ceNote(186, 104, 0.65, '#fef9c3', '-1.3s');
    s += K.vol('M128 104C140 110 146 120 148 130C144 136 138 136 136 132C134 124 130 118 124 114Z', robe) + K.vol(K.ell(146, 132, 6.5, 6), skin);
    // котёл изобилия
    s += `<circle class="art-aura" cx="52" cy="140" r="30" fill="${K.rad([[0, '#fef08a', 0.6], [1, '#facc15', 0]])}"/>`;
    s += K.line('M40 176L36 182M64 176L68 182', '#000', 4);
    s += K.vol('M20 142C18 164 32 178 52 178C72 178 86 164 84 142Z', iron);
    s += `<ellipse cx="52" cy="142" rx="33" ry="7.5" fill="#1f2937" stroke="#000" stroke-width="2.2"/><ellipse cx="52" cy="142" rx="28" ry="5.4" fill="${K.lin(['#fef08a', '#f59e0b'])}"/>`;
    s += `<g class="art-blink"><circle cx="42" cy="141" r="2.4" fill="#fef9c3"/><circle cx="60" cy="143" r="1.8" fill="#fef9c3"/><circle cx="50" cy="140" r="1.4" fill="#fef9c3"/></g>`;
    s += K.line('M36 132c-4-8 4-12 0-20M52 128c-4-8 4-12 0-20M68 132c-4-8 4-12 0-20', '#f8fafc', 2, { op: 0.5, cls: 'art-float' });
    s += K.stitch('M24 156Q52 166 80 156', '#fbbf24', 1.6);
    // черпак в правой руке
    s += K.line('M58 142L76 110', '#713f12', 5) + K.line('M58 142L76 110', '#b45309', 2.4);
    s += K.vol('M72 98C62 104 58 112 60 118C66 122 72 120 76 116C78 110 80 104 84 100Z', robe) + K.vol(K.ell(74, 112, 6.5, 6), skin);
    // голова, борода
    s += K.vol(K.ell(100, 56, 20, 20), skin);
    s += K.mirror(K.vol('M82 44C74 50 72 62 76 72L84 66C82 58 84 50 88 46Z', beard));
    s += K.vol('M74 58C70 86 80 110 100 120C120 110 130 86 126 58C120 74 110 80 100 80C90 80 80 74 74 58Z', beard);
    s += K.line('M84 84q-3 10 0 20M100 88v22M116 84q3 10 0 20M92 96q-2 6 0 12M108 96q2 6 0 12', '#9a3412', 1.6, { op: 0.8 });
    s += K.mirror(K.part('M100 72C94 68 84 70 78 78C82 80 90 79 100 78Z', '#fb923c', { line: '#5a1a06', lw: 1.4 }));
    s += `<path d="M90 80Q100 92 110 80Q100 84 90 80Z" fill="#6b1d2a" stroke="${K.INK}" stroke-width="1.8" stroke-linejoin="round"/>`;
    s += `<ellipse cx="100" cy="66" rx="5.4" ry="4.4" fill="${K.rad([[0, '#fbbf9a'], [1, '#d97a55']], 0.4, 0.35, 0.7)}" stroke="#7a3a1a" stroke-width="1.4"/>`;
    s += K.eyes(100, 54, 9, 6, { iris: '#78350f', look: [0, 0.2] }) + K.blush(82, 64, 4.6) + K.blush(118, 64, 4.6);
    s += K.mirror(K.part('M92 45C88 42 82 42 78 46C82 46 86 47 90 49Z', '#c2410c', { line: '#5a1a06', lw: 1.2 }));
    // дубовый венок с желудями
    for (const [x, y, r] of [[78, 42, -150], [86, 36, -120], [96, 34, -95], [104, 34, -85], [114, 36, -60], [122, 42, -30]]) s += ceOak(K, x, y, 16, r);
    const acorn = (x, y) => `<ellipse cx="${x}" cy="${y + 2}" rx="3" ry="3.8" fill="${K.lin(['#fcd34d', '#b45309'])}" stroke="#451a03" stroke-width="1"/><path d="M${x - 3.6} ${y}Q${x} ${y - 4} ${x + 3.6} ${y}Z" fill="#78350f" stroke="#451a03" stroke-width="1"/>`;
    s += acorn(90, 36) + acorn(110, 36);
    s += K.spark(20, 60, 3.4, '#fef9c3', 'art-float') + K.spark(180, 30, 3, '#fde68a') + K.spark(26, 104, 2.6, '#bef264') + K.spark(174, 150, 2.4, '#fef9c3', 'art-float');
    return s;
  },

  // Луг (легенда): сияющий бог, мастер всех искусств. Юный воин в золотой тунике и фиолетовом плаще, за головой —
  // солнечный венец лучей, на шее — золотая гривна-торквес. В правой руке огненное копьё, по которому бегут молнии,
  // в левой — круглый щит с трискелем; вокруг кружат знаки его искусств: молот кузнеца, арфа и перо поэта
  ce_lugh(K) {
    const f = K.f;
    const skin = { c1: '#fde7d2', c2: '#dba684', rim: '#fff6b0', tex: false, lw: 2.2, line: '#6a3a1a' };
    const gold = { c1: '#fef9c3', c2: '#ca8a04', rim: '#fff6b0', rimK: 0.6, texK: 0.25, lw: 2.4, line: '#713f12' };
    const cape = { c1: '#a78bfa', c2: '#3b0764', rim: '#fff6b0', rimK: 0.55, tex: false, lw: 2.4, line: '#1e0533' };
    let s = K.aura('#facc15', 100, 96, 0.55) + K.aura('#a78bfa', 70, 110, 0.3);
    // солнечный венец
    let rays = '';
    for (let i = 0; i < 18; i++) {
      const a = i * 20 * Math.PI / 180, r2 = i % 2 ? 46 : 56, w = 0.1;
      rays += `M${f(100 + 30 * Math.cos(a - w))} ${f(56 + 30 * Math.sin(a - w))}L${f(100 + r2 * Math.cos(a))} ${f(56 + r2 * Math.sin(a))}L${f(100 + 30 * Math.cos(a + w))} ${f(56 + 30 * Math.sin(a + w))}Z`;
    }
    s += `<g class="art-spin-soft"><path d="${rays}" fill="${K.rad([[0.55, '#fffbe6'], [1, '#facc15']])}" stroke="#ca8a04" stroke-width="1.2" stroke-linejoin="round"/></g>`;
    s += `<circle cx="100" cy="56" r="32" fill="${K.rad([[0, '#fffbe6', 1], [0.7, '#fef08a', 0.9], [1, '#facc15', 0.85]])}" stroke="#ca8a04" stroke-width="2"/>` + ceTriskele(K, 100, 56, 28, '#fbbf24', 1.6);
    // плащ
    s += K.vol('M100 76C128 78 144 98 150 124C156 148 158 164 158 176H42C42 164 44 148 50 124C56 98 72 78 100 76Z', cape);
    s += K.stitch('M44 172H156', '#fde68a', 1.8);
    // сапоги
    s += K.mirror(K.vol('M80 160H96V172C96 176 94 179 90 179H76C74 176 76 172 80 170Z', { c1: '#a16207', c2: '#422006', tex: false, lw: 2, line: '#1c0a02' }));
    // туника
    s += K.vol('M100 84C116 84 126 96 128 112L134 160C120 168 80 168 66 160L72 112C74 96 84 84 100 84Z', gold);
    s += K.part('M71 126Q100 134 129 126L130 134Q100 142 70 134Z', '#6d28d9', { line: '#1e0533', lw: 1.6 }) + K.rhomb(100, 134, 4, '#facc15', '#713f12');
    s += K.stitch('M68 156Q100 166 132 156', '#6d28d9', 1.8) + K.line('M100 140V160', '#ca8a04', 1.4, { op: 0.6 });
    // знаки искусств
    const hammer = `<g class="art-float" style="animation-delay:-.4s"><g transform="translate(26 36) rotate(-30)">${K.line('M0 0V16', '#78350f', 3)}${K.part('M-7 -5H7V1H-7Z', '#cbd5e1', { line: '#334155', lw: 1.2 })}</g></g>`;
    const harp = `<g class="art-float" style="animation-delay:-1.2s"><g transform="translate(22 92)">${K.line('M-6 10C-8 0 -4 -8 4 -10M4 -10L6 10M-6 10H6', '#facc15', 2.2)}${K.line('M-3 6L3 -4M-4 2L4 -7', '#fef9c3', 0.9)}</g></g>`;
    const quill = `<g class="art-float" style="animation-delay:-.8s"><g transform="translate(176 44) rotate(30)"><path d="M0 12C-6 2 -4 -10 4 -16C6 -6 4 4 0 12Z" fill="#f8fafc" stroke="#475569" stroke-width="1.2"/>${K.line('M0 12L2 -12', '#94a3b8', 1)}</g></g>`;
    s += hammer + harp + quill;
    // щит с трискелем в левой руке
    s += K.vol('M74 98C62 104 56 114 54 124C58 130 64 130 66 126C68 118 72 112 80 108Z', gold);
    s += `<circle cx="46" cy="132" r="25" fill="${K.rad([[0, '#c4b5fd'], [0.7, '#7c3aed'], [1, '#3b0764']], 0.4, 0.35, 0.8)}" stroke="#1e0533" stroke-width="2.6"/>`;
    s += `<circle cx="46" cy="132" r="20" fill="none" stroke="#facc15" stroke-width="2.4"/>` + ceTriskele(K, 46, 132, 15, '#fde68a', 2.4);
    s += [0, 60, 120, 180, 240, 300].map(a => `<circle cx="${f(46 + 22.5 * Math.cos(a * Math.PI / 180))}" cy="${f(132 + 22.5 * Math.sin(a * Math.PI / 180))}" r="1.6" fill="#fef9c3"/>`).join('');
    s += K.gloss(36, 120, 6, 3, -40, 0.4);
    // копьё с молниями в правой руке
    s += `<circle class="art-aura" cx="160" cy="30" r="22" fill="${K.rad([[0, '#fffbe6', 0.95], [0.4, '#fde047', 0.6], [1, '#facc15', 0]])}"/>`;
    s += K.line('M150 178L160 40', '#422006', 5.6) + K.line('M150 178L160 40', '#d97706', 2.8);
    s += K.part('M161 8C168 20 168 32 161 44C154 32 154 20 161 8Z', '#fffbe6', { line: '#ca8a04', lw: 1.8 }) + K.line('M161 14V40', '#fde047', 1.4);
    s += K.part('M152 44H170L166 50H156Z', '#facc15', { line: '#713f12', lw: 1.4 });
    s += K.line('M150 20l-8 6l6 2l-8 8M172 18l8 6l-6 2l8 8M156 60l-6 8l5 1l-6 9M168 70l6 6l-5 2l6 7', '#fde047', 2.2, { cls: 'art-blink' });
    s += K.vol('M126 98C138 102 146 110 150 120C148 126 142 128 140 124C136 118 130 112 122 108Z', gold) + K.vol(K.ell(153, 118, 6.5, 6), skin);
    // торквес
    s += K.line('M84 90Q100 102 116 90', '#ca8a04', 5.4) + K.line('M84 90Q100 102 116 90', '#fde047', 2.6) + `<circle cx="84" cy="90" r="3.4" fill="#facc15" stroke="#713f12" stroke-width="1.2"/><circle cx="116" cy="90" r="3.4" fill="#facc15" stroke="#713f12" stroke-width="1.2"/>`;
    // голова, золотые волосы
    s += K.mirror(K.vol('M86 50C76 58 74 72 76 84C80 88 86 86 86 80C86 70 88 62 92 56Z', { c1: '#fef08a', c2: '#ca8a04', rim: '#fffbe6', tex: false, lw: 2, line: '#713f12' }));
    s += K.vol(K.ell(100, 64, 16, 18), skin);
    s += K.part('M84 62C82 48 90 42 100 42C110 42 118 48 116 62C110 54 104 52 96 54C92 56 88 58 84 62Z', '#fde047', { line: '#713f12', lw: 1.6 });
    s += K.part('M84 50Q100 42 116 50L116 55Q100 47 84 55Z', '#facc15', { line: '#713f12', lw: 1.4 }) + K.rhomb(100, 48, 3, '#a78bfa', '#3b0764');
    s += K.eyes(100, 66, 7.4, 5.8, { iris: '#ca8a04', look: [0.4, 0] });
    s += K.line('M88 58Q92 56 96 58M104 58Q108 56 112 58', '#a16207', 1.6) + K.blush(88, 74, 3.6) + K.blush(112, 74, 3.6) + K.mouth('smile', 100, 76, 9);
    s += K.spark(186, 130, 3, '#fde047', 'art-float') + K.spark(14, 160, 2.6, '#fef9c3') + K.spark(120, 16, 2.6, '#fffbe6', 'art-float');
    return s;
  },
});

/* ---------- кисть кельтских духов: вспомогательные рисунки ---------- */
// обрезка по контуру (для заливок поверх vol)
function ceClip(K, d, inner) {
  const i = K.id('c');
  K.def(`<clipPath id="${i}"><path d="${d}"/></clipPath>`);
  return `<g clip-path="url(#${i})">${inner}</g>`;
}
// вертикальный градиент с прозрачностью в координатах холста: [[offset, цвет, прозрачность], …]
function ceLinA(K, stops, y1, y2) {
  const i = K.id('a');
  K.def(`<linearGradient id="${i}" gradientUnits="userSpaceOnUse" x1="0" y1="${y1}" x2="0" y2="${y2}">${stops.map(([o, c, a]) => `<stop offset="${o}" stop-color="${c}" stop-opacity="${a}"/>`).join('')}</linearGradient>`);
  return `url(#${i})`;
}
// пунктир из светящихся точек по пути
function ceDots(d, c, w, gap, op) {
  return `<path class="art-blink" d="${d}" fill="none" stroke="${c}" stroke-width="${w}" stroke-linecap="round" stroke-dasharray=".1 ${gap}" opacity="${op}"/>`;
}
// нотка песни
function ceNote(x, y, k, c, d) {
  return `<g class="art-float" style="animation-delay:${d}"><g transform="translate(${x} ${y}) scale(${k})"><path d="M3.4 0V-15Q9 -12 10 -6" fill="none" stroke="${c}" stroke-width="2.2" stroke-linecap="round"/><ellipse cx="0" cy="0" rx="4.4" ry="3.2" transform="rotate(-22)" fill="${c}"/></g></g>`;
}
// трилистник (four — четырёхлистник): центр, размер листка, поворот, цвет
function ceShamrock(K, x, y, r, rot, c, four) {
  const f = K.f;
  const leaf = `M0 0C${f(-r * 0.25)} ${f(-r * 0.35)} ${f(-r * 1.05)} ${f(-r * 0.45)} ${f(-r * 0.7)} ${f(-r * 1.05)}C${f(-r * 0.45)} ${f(-r * 1.35)} ${f(-r * 0.05)} ${f(-r * 1.25)} 0 ${f(-r * 0.95)}` +
    `C${f(r * 0.05)} ${f(-r * 1.25)} ${f(r * 0.45)} ${f(-r * 1.35)} ${f(r * 0.7)} ${f(-r * 1.05)}C${f(r * 1.05)} ${f(-r * 0.45)} ${f(r * 0.25)} ${f(-r * 0.35)} 0 0Z`;
  const fill = K.lin([K.shade(c, 0.35), c, K.shade(c, -0.25)]);
  let s = K.line(`M0 0Q${f(r * 0.3)} ${f(r * 0.8)} ${f(r * 0.1)} ${f(r * 1.5)}`, K.shade(c, -0.4), Math.max(1.5, r * 0.16));
  for (const a of four ? [-45, 45, 135, 225] : [0, 120, 240]) {
    s += `<path d="${leaf}" transform="rotate(${a})" fill="${fill}" stroke="${K.shade(c, -0.55)}" stroke-width="${f(Math.max(1, r * 0.09))}" stroke-linejoin="round"/>` +
      `<path d="M0 ${f(-r * 0.15)}V${f(-r * 0.8)}" transform="rotate(${a})" stroke="${K.shade(c, 0.45)}" stroke-width="${f(Math.max(0.8, r * 0.06))}" opacity=".7"/>`;
  }
  return `<g transform="translate(${x} ${y}) rotate(${rot})">${s}</g>`;
}
// трикветр — кельтский узел из трёх дуг и кольца
function ceTriquetra(K, x, y, r, c, w) {
  const f = K.f, P = i => { const a = (-90 + i * 120) * Math.PI / 180; return `${f(x + r * Math.cos(a))} ${f(y + r * Math.sin(a))}`; }, R = f(r * 0.95);
  return K.line(`M${P(0)}A${R} ${R} 0 0 0 ${P(2)}A${R} ${R} 0 0 0 ${P(1)}A${R} ${R} 0 0 0 ${P(0)}Z`, c, w) + `<circle cx="${x}" cy="${y}" r="${f(r * 0.5)}" fill="none" stroke="${c}" stroke-width="${f(w * 0.8)}"/>`;
}
// трискель — три спирали из общего центра
function ceTriskele(K, x, y, R, c, w) {
  const f = K.f;
  let d = '';
  for (let i = 0; i < 3; i++) {
    const a = (-90 + i * 120) * Math.PI / 180, dd = R * 0.52, cx = x + dd * Math.cos(a), cy = y + dd * Math.sin(a), T = Math.PI * 3.2, p0 = a + Math.PI - T;
    for (let k = 0; k <= 40; k++) { const t = k / 40, ph = p0 + T * t, rr = dd * t; d += `${k ? 'L' : 'M'}${f(cx + rr * Math.cos(ph))} ${f(cy + rr * Math.sin(ph))}`; }
  }
  return K.line(d, c, w);
}
// ворон в полёте: x, y, масштаб, зеркально, задержка анимации
function ceRaven(K, x, y, k, flip, d) {
  const b = `<path d="M0 0C-6 -8 -16 -13 -26 -9C-18 -6 -12 -2 -8 4ZM0 0C6 -10 16 -15 26 -13C18 -9 12 -4 8 4Z" fill="${K.lin(['#6b7280', '#111827'])}" stroke="#000" stroke-width="1.3" stroke-linejoin="round"/>` +
    `<path d="M-8 3L-16 1L-15 7Z" fill="#111827" stroke="#000" stroke-width="1.1" stroke-linejoin="round"/><ellipse cx="0" cy="3" rx="10" ry="4.4" fill="#1f2937" stroke="#000" stroke-width="1.3"/>` +
    `<circle cx="10" cy="1" r="3.8" fill="#1f2937" stroke="#000" stroke-width="1.2"/><path d="M13 0L19 2L13 3.6Z" fill="#6b7280" stroke="#000" stroke-width=".9"/><circle cx="11" cy="0" r="1.1" fill="#f87171"/>`;
  return `<g class="art-float" style="animation-delay:${d}"><g transform="translate(${x} ${y}) scale(${flip ? -k : k} ${k})">${b}</g></g>`;
}
// трискелион острова Мэн — три бегущие ноги
function ceThreeLegs(K, x, y, r, c) {
  const f = K.f;
  let d = '';
  for (let i = 0; i < 3; i++) {
    const a = (-90 + i * 120) * Math.PI / 180, b = a + Math.PI * 0.45;
    const kx = x + r * 0.62 * Math.cos(a), ky = y + r * 0.62 * Math.sin(a), fx = kx + r * 0.6 * Math.cos(b), fy = ky + r * 0.6 * Math.sin(b);
    d += `M${f(x)} ${f(y)}L${f(kx)} ${f(ky)}L${f(fx)} ${f(fy)}l${f(r * 0.3 * Math.cos(a))} ${f(r * 0.3 * Math.sin(a))}`;
  }
  return K.line(d, c, f(r * 0.26));
}
// дубовый лист: основание (x, y), длина, поворот
function ceOak(K, x, y, len, rot) {
  const k = K.f(len / 22);
  return `<g transform="translate(${x} ${y}) rotate(${rot}) scale(${k})"><path d="M0 0C2 -3 5 -2 6 -4C8 -7 11 -5 12 -7C14 -10 17 -7 18 -8C21 -8 23 -4 20 -2C23 0 21 4 18 3C17 6 14 5 12 5C10 8 7 6 6 5C4 5 2 3 0 0Z" fill="${K.lin(['#a3e635', '#4d7c0f'])}" stroke="#1a2e05" stroke-width="1.4" stroke-linejoin="round"/><path d="M1 0H18" stroke="#1a2e05" stroke-width=".9"/></g>`;
}
// точки на кубической кривой Безье p = [x0, y0, x1, y1, x2, y2, x3, y3]: n + 1 точек [x, y, угол касательной в градусах]
function ceBez(p, n) {
  const out = [];
  for (let i = 0; i <= n; i++) {
    const t = i / n, u = 1 - t;
    const x = u * u * u * p[0] + 3 * u * u * t * p[2] + 3 * u * t * t * p[4] + t * t * t * p[6];
    const y = u * u * u * p[1] + 3 * u * u * t * p[3] + 3 * u * t * t * p[5] + t * t * t * p[7];
    const dx = 3 * u * u * (p[2] - p[0]) + 6 * u * t * (p[4] - p[2]) + 3 * t * t * (p[6] - p[4]);
    const dy = 3 * u * u * (p[3] - p[1]) + 6 * u * t * (p[5] - p[3]) + 3 * t * t * (p[7] - p[5]);
    out.push([x, y, Math.atan2(dy, dx) * 180 / Math.PI]);
  }
  return out;
}
// коса-плетёнка (хвост, прядь) вдоль кривой p: звенья-овалы наклонены то вправо, то влево
function cePlait(K, p, n, r, c1, c2, line) {
  const f = K.f, g = K.lin([c1, c2]);
  return ceBez(p, n).map(([x, y, a], i) => {
    const k = 1 - i / (n + 4);
    return `<ellipse cx="${f(x)}" cy="${f(y)}" rx="${f(r * k)}" ry="${f(r * 0.62 * k)}" transform="rotate(${f(a + (i % 2 ? 32 : -32))} ${f(x)} ${f(y)})" fill="${g}" stroke="${line}" stroke-width="1.4"/>`;
  }).join('');
}
// вода по пояс: волнистая кромка на высоте y от x0 до x1 (шаг волны 20), заливка до y2
function ceWater(K, y, x0, x1, y2, c1, c2, foam) {
  let wv = `M${x0} ${y}`;
  for (let x = x0; x < x1; x += 20) wv += `Q${x + 5} ${y - 6} ${x + 10} ${y}T${x + 20} ${y}`;
  return `<path d="${wv}L${x1} ${y2}L${x0} ${y2}Z" fill="${ceLinA(K, [[0, c1, 0.85], [1, c2, 0.95]], y - 6, y2)}"/>` + K.line(wv, foam, 2.2);
}
// пушистый контур (пух, облако, пена): овал (cx, cy, rx, ry) из n «пушинок» высотой b
function ceFluff(K, cx, cy, rx, ry, n, b, a0 = 0) {
  const f = K.f, P = (a, k) => [f(cx + (rx + k) * Math.cos(a * Math.PI / 180)), f(cy + (ry + k) * Math.sin(a * Math.PI / 180))];
  let d = `M${P(a0, 0).join(' ')}`;
  for (let i = 1; i <= n; i++) d += `Q${P(a0 + (i - 0.5) * 360 / n, b).join(' ')} ${P(a0 + i * 360 / n, 0).join(' ')}`;
  return d + 'Z';
}
// лента вдоль кривой p (водоросль, прядь, язык пламени): ширина w у основания сходит на нет к кончику, wob — волнистый край
function ceRibbon(K, p, w, c, line, wob) {
  const f = K.f, n = 16, pts = ceBez(p, n), L = [], R = [];
  pts.forEach(([x, y, a], i) => {
    const t = i / n, ww = w * (1 - t * 0.88) * (1 + (wob ? 0.22 * Math.sin(i * 1.9) : 0)) / 2, r = (a + 90) * Math.PI / 180;
    L.push(`${f(x + ww * Math.cos(r))} ${f(y + ww * Math.sin(r))}`); R.push(`${f(x - ww * Math.cos(r))} ${f(y - ww * Math.sin(r))}`);
  });
  return K.part(`M${L.join('L')}L${R.reverse().join('L')}Z`, c, { line, lw: 1.6 }) + K.line(`M${pts.slice(0, n - 2).map(([x, y]) => `${f(x)} ${f(y)}`).join('L')}`, K.shade(c, 0.45), 1, { op: 0.6 });
}
// ракушка-гребешок: «замок» в (x, y), веер длиной r, поворот rot (0 — веер вверх), цвет c
function ceShell(K, x, y, r, rot, c) {
  const f = K.f, G = K._ceShell = K._ceShell || {};
  const g = G[c] || (G[c] = K.lin([K.shade(c, 0.45), c, K.shade(c, -0.22)]));
  let ribs = '';
  for (let i = -2; i <= 2; i++) ribs += `M0 0L${f(i * r * 0.3)} ${f(-r * 0.92)}`;
  return `<g transform="translate(${x} ${y}) rotate(${rot})"><path d="M0 0L${f(-r * 0.72)} ${f(-r * 0.5)}Q${f(-r * 0.62)} ${f(-r * 1.1)} 0 ${f(-r * 1.06)}Q${f(r * 0.62)} ${f(-r * 1.1)} ${f(r * 0.72)} ${f(-r * 0.5)}Z" fill="${g}" stroke="${K.shade(c, -0.62)}" stroke-width="1.1" stroke-linejoin="round"/>` +
    `<path d="${ribs}" stroke="${K.shade(c, -0.38)}" stroke-width=".8"/></g>`;
}
// ветка остролиста: основание (x, y), длина ветки len, поворот rot, размер листьев k; колючие листья и три ягоды на конце
function ceHolly(K, x, y, len, rot, k = 1) {
  const f = K.f, g = K.lin(['#4ade80', '#166534']);
  const leaf = (px, a, s) => `<g transform="translate(${f(px)} 0) rotate(${a}) scale(${f(s * k)})"><path d="M0 0C2 -4 4 -6 6 -5L8 -9L10 -6L13 -9L15 -5L18 -7L19 -3L23 0L19 3L18 7L15 5L13 9L10 6L8 9L6 5C4 6 2 4 0 0Z" fill="${g}" stroke="#052e16" stroke-width="1.2" stroke-linejoin="round"/><path d="M1 0H20" stroke="#bbf7d0" stroke-width=".8" opacity=".7"/></g>`;
  let lv = '';
  for (let i = 0; i < 3; i++) { const px = len * (0.18 + i * 0.27); lv += leaf(px, -48 + i * 6, 1 - i * 0.06) + leaf(px + 7, 44 - i * 6, 0.92 - i * 0.06); }
  const b = (dx, dy, r, c) => `<circle cx="${f(len + dx * k)}" cy="${f(dy * k)}" r="${f(r * k)}" fill="${c}" stroke="#7f1d1d" stroke-width="1"/>`;
  return `<g transform="translate(${x} ${y}) rotate(${rot})">${K.line(`M0 0L${len} 0`, '#3f2a14', 3.4)}${lv}${b(0, -3, 3.6, '#ef4444')}${b(4, 2, 3.4, '#dc2626')}${b(-2, 3, 3.2, '#f87171')}<circle cx="${f(len - 1 * k)}" cy="${f(-4 * k)}" r="1" fill="#fff" opacity=".8"/></g>`;
}
// крест святой Бригиты из тростника: центр (x, y), размах r — четыре связанных пучка вертушкой вокруг плетёного квадрата
function ceBrigidCross(K, x, y, r, c = '#e9c46a') {
  const f = K.f, w = r * 0.3, g = K.lin([K.shade(c, 0.35), c, K.shade(c, -0.3)]), ln = K.shade(c, -0.6);
  let s = '';
  for (let i = 0; i < 4; i++) {
    s += `<g transform="rotate(${i * 90} ${x} ${y})"><path d="M${f(x)} ${f(y - w * 0.2)}h${f(r)}v${f(w)}h${f(-r)}Z" fill="${g}" stroke="${ln}" stroke-width="1.2"/>` +
      `<path d="M${f(x + r * 0.3)} ${f(y - w * 0.2)}l${f(r * 0.5)} 0M${f(x + r * 0.3)} ${f(y + w * 0.3)}l${f(r * 0.5)} 0" stroke="${K.shade(c, -0.4)}" stroke-width=".8"/>` +
      `<rect x="${f(x + r * 0.78)}" y="${f(y - w * 0.32)}" width="${f(w * 0.42)}" height="${f(w * 1.24)}" rx="1" fill="#a16207" stroke="${ln}" stroke-width=".8"/></g>`;
  }
  return s + `<rect x="${f(x - w * 0.7)}" y="${f(y - w * 0.7)}" width="${f(w * 1.4)}" height="${f(w * 1.4)}" fill="${g}" stroke="${ln}" stroke-width="1.4"/>` +
    `<path d="M${f(x - w * 0.7)} ${y}h${f(w * 1.4)}M${x} ${f(y - w * 0.7)}v${f(w * 1.4)}" stroke="${ln}" stroke-width=".9"/>`;
}
// белый пёс Аннуна с алыми ушами, сидит: x, y — у земли, k — масштаб, left — смотрит влево
function ceHound(K, x, y, k, left) {
  const w = { c1: '#ffffff', c2: '#a8b3c7', rim: '#e9d5ff', rimK: 0.6, tex: false, lw: 2, line: '#334155' };
  let b = K.line('M-12 -4C-22 -6 -26 -16 -20 -22', '#334155', 6) + K.line('M-12 -4C-22 -6 -26 -16 -20 -22', '#f1f5f9', 3.4);
  b += K.vol('M-14 0C-18 -12 -14 -28 -2 -32C8 -34 16 -28 16 -16C16 -8 14 -4 12 0Z', w);
  b += K.vol('M2 -18V0H10V-18Z', w) + K.part('M0 -2H12V2H0Z', '#e2e8f0', { line: '#334155', lw: 1.2 });
  b += K.vol('M-2 -30C-6 -38 -2 -48 8 -50C16 -51 22 -46 24 -40C28 -38 31 -34 29 -30C25 -27 18 -28 12 -27C6 -25 0 -25 -2 -30Z', w);
  b += K.part('M4 -44L-1 -58L12 -47Z', '#ef4444', { line: '#7f1d1d', lw: 1.3 }) + K.part('M12 -46L13 -58L20 -44Z', '#dc2626', { line: '#7f1d1d', lw: 1.3 });
  b += `<circle cx="14" cy="-40" r="2.2" fill="#7f1d1d"/><circle cx="14.6" cy="-40.8" r=".8" fill="#fff"/><ellipse cx="29" cy="-34" rx="2.4" ry="2" fill="#334155"/>`;
  return `<g transform="translate(${x} ${y}) scale(${left ? -k : k} ${k})">${b}</g>`;
}
// маленький лебедь на воде: x, y — у воды, k — масштаб, flip — смотрит вправо
function ceSwan(K, x, y, k, flip, c = '#ffffff') {
  const neck = 'M-9 -3C-15 -11 -15 -20 -8 -24';
  const b = `<path d="M-14 0C-15 -6 -9 -9 0 -8C8 -8 13 -5 15 -1C11 3 3 4 -5 3C-10 3 -13 2 -14 0Z" fill="${K.lin([c, K.shade(c, -0.25)])}" stroke="#3b4a6b" stroke-width="1.3" stroke-linejoin="round"/>` +
    K.line(neck, '#3b4a6b', 4.6) + K.line(neck, c, 2.4) + `<ellipse cx="-7.5" cy="-24" rx="3.4" ry="2.7" fill="${c}" stroke="#3b4a6b" stroke-width="1.1"/>` +
    `<path d="M-10 -25L-16 -22.6L-10 -21.6Z" fill="#fb923c" stroke="#7c2d12" stroke-width=".6"/>` + K.line('M-3 -4Q4 -8 10 -3', '#94a3b8', 1.1);
  return `<g transform="translate(${x} ${y}) scale(${flip ? -k : k} ${k})">${b}</g>`;
}

/* ---------- 5.2: новые духи и боги кельтской мифологии (расширение до 63 видов) ---------- */
