    s += K.vol(cape, cloak);
    s += K.line('M78 108C72 128 68 148 64 166M122 108C128 128 132 148 136 166', '#1a0633', 1.6, { op: 0.4 });
    // сапожки
    s += K.mirror(K.vol('M80 166C80 160 88 158 95 161C98 163 98 172 96 178H79C78 174 78 170 80 166Z', { c1: '#7c4a1d', c2: '#2a1206', tex: false, lw: 2, line: '#1c0a02' }));
    // туника и пояс с трискелем
    s += K.vol('M100 90C115 90 124 102 126 118L131 164C118 170 82 170 69 164L74 118C76 102 85 90 100 90Z', tunic);
    s += K.part('M73 124Q100 132 127 124L128 133Q100 141 72 133Z', '#4c1d95', { line: '#1a0633', lw: 1.6 });
    s += `<circle cx="100" cy="133" r="6.5" fill="${K.lin(['#fef08a', '#ca8a04'])}" stroke="#713f12" stroke-width="1.4"/>` + ceTriskele(K, 100, 133, 4.6, '#713f12', 1);
    s += K.stitch('M71 160Q100 168 129 160', '#fde68a', 1.4) + K.line('M100 140V164', '#7c2d12', 1.4, { op: 0.5 });
    // арфа: колонна, светящиеся струны, дека и изогнутая шейка
