    const pil = 'M30 104C24 126 30 148 44 162', box = 'M70 98L44 162', neck = 'M30 104C44 92 58 92 70 98';
    s += K.line(pil, '#4a2004', 7) + K.line(pil, '#f6c453', 3.6);
