    for (let i = 0; i < 6; i++) { const x = 44 + i * 4.4; strings += `M${f(x)} ${f(96 - Math.sin((x - 30) / 40 * Math.PI) * 2)}V${f(98 + (70 - x) / 26 * 64 - 2)}`; }
