    const body = 'M100 40C134 40 154 62 158 92C162 120 160 146 158 164L151 158L145 168L137 160L129 170L121 162L113 171L106 163L100 172L94 163L87 171L79 162L71 170L63 160L55 168L49 158L42 164C40 146 38 120 42 92C46 62 66 40 100 40Z';
    s += K.vol(body, fur);
    s += K.line('M54 116C52 134 54 150 58 162M70 122C68 140 70 154 74 166M130 122C132 140 130 154 126 166M146 116C148 134 146 150 142 162M92 134C90 148 92 158 94 168M108 134C110 148 108 158 106 168', '#4a2a12', 1.6, { op: 0.55 });
    s += K.gloss(68, 62, 10, 5.5, -40, 0.35);
    // глаза из-под чёлки, нос картошкой, улыбка
    s += K.eyes(100, 92, 16, 10, { iris: '#7c4a1d', look: [0.2, 0.1] });
    s += K.part('M58 88C60 62 78 48 100 48C122 48 140 62 142 88L136 82L130 90L123 81L116 89L109 80L100 88L91 80L84 89L77 81L70 90L64 82Z', '#a87442', { line: '#24120a', lw: 1.8 });
    s += K.line('M72 64L76 80M88 56L90 74M104 54V72M120 58L116 76M132 66L128 80', '#4a2a12', 1.4, { op: 0.55 });
    s += `<ellipse cx="100" cy="108" rx="10.5" ry="8.6" fill="${K.rad([[0, '#fbbf9a'], [1, '#d97a55']], 0.4, 0.35, 0.7)}" stroke="#6a3a1a" stroke-width="1.8"/><ellipse cx="97" cy="105" rx="3.2" ry="1.9" fill="#fff" opacity=".7"/>`;
    s += K.blush(78, 110, 5.4) + K.blush(122, 110, 5.4) + K.mouth('grin', 100, 120, 20);
    // левая лапища на мраморе
